quests[10839] = { id = 10839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veil Skith: Darkstone of Terokk", description = "Veil Skith lies to the northwest of the caravan and to the south of Shattrath in a secluded grove of the forest. It is rumored that the colony of Skettis has constructed a maligned altar of worship. This Darkstone of Terokk must be purified if the arakkoa of Skith are ever to be redeemed.\n\nTake this Rod of Purification and cast it upon the Darkstone. Blessed by A'dal, the rod's purity might be enough to bring clarity to the Darkstone. Go now and may the light shine upon thee.", sourceObjective = "Use the Rod of Purification on the Darkstone of Terokk in Veil Skith and return to Kirrik the Awakened at the Refugee Caravan in the Bone Wastes.", progress = "Darkness surrounds us. What have you to say about Veil Skith?", completion = "I heard the explosion from here. Not with my ears, but with my heart.\n\nIf the touch of the blessed Naaru, A'dal, is not enough to bring the arakkoa to redemption, nothing will be. Those who have not given themselves over to the Light are mere servants of evil.\n\nThey must be destroyed.", sourceObjectiveStatus = "unverified-source-field" }
quests[10840] = { id = 10840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tomb of Lights", description = "To the east, buried under the charred sand, is the Tomb of Lights, a lost resting place of the dead.  Before our caravan was ambushed I was going to journey to the tomb and cleanse it of evil spirits.  \n\nLittle did I know it was already infested with another kind of evil.  Even now the ethereals plunder the bodies of the fallen for trinkets and keepsakes that were given to the dead centuries ago.  \n\nThere is little I can do while our caravan struggles to survive.", sourceObjective = "High Priest Orglum wants you to journey to the Tomb of Lights and kill 10 Ethereal Nethermancers and 10 Ethereal Plunderers and then return to him at the Refugee Caravan.", progress = "How many ethereals have you destroyed?  I hope it will be enough to drive them from the Tomb of Lights.", completion = "Out here in the wilds of Outland we are weak with few heroes to defend our rights, but you have given them something to fear {class}.  I do not think the ethereals will soon forget the strong right arm of {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10842] = { id = 10842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeful Souls", description = "The Tomb of Lights has become corrupted by the Shadow Council and the draenei dead have become cursed spirits, angry and confused with a burning hatred for the living.\n\nEnter the tomb and seek out these tragic victims. Give them the rest that they deserve.", sourceObjective = "High Priest Orglum wants you to journey into the Tomb of Lights and defeat 5 Vengeful Draenei.", progress = "You have saved us all.  What can we do to thank you?", completion = "You cannot know what you have done here {name}.  You have saved so many of us from an eternity of darkness.  There is little that I can do for the living and nothing that I could give that would thank you enough.  Take what seems useful to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10843] = { id = 10843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Since Time Forgotten...", description = "Since time forgotten we have fought with the Bladespire ogres.\n\nWe have managed to push them back so that now they only hold a tenuous grip at Bladespire Outpost.  It's back the way that you came, on the southwestern edge of the Razor Ridge.\n\nProve your worth to me by killing their leader, Gnosh Brognat.\n\nLet us see what stuff you are made of when fighting the ogres.", sourceObjective = "Slay Gnosh Brognat, leader of the ogres at the Bladespire Outpost.", completion = "<Leoroxx appraises you with a keen eye, seemingly trying to take your measure.>\n\nThe death of Gnosh Brognat is a boon to all of the Mok'Nathal.  This is a good thing for you.\n\nLet us see if we can push the boundaries of your prowess just a bit more.", sourceObjectiveStatus = "unverified-source-field" }
quests[10844] = { id = 10844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Camp: Anger" }
quests[10845] = { id = 10845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay the Brood Mother", description = "My hunters have just returned from a scouting mission to the Singing Ridge.  It seems that the nether drakes, which infest the crystals there, have increased greatly in number, and threaten to spill out into our laps.\n\nSince you have proven yourself a competent slayer, let us see if your {class} skills are the match of an adult drake.\n\nFind the Singing Ridge by heading south through the Scalewing Shelf.  Enter and slay their brood mother, Dreadwing.", sourceObjective = "Slay Dreadwing.", progress = "Though you will not further yourself in my eyes, there is no shame in admitting that you aren't up to the challenge of slaying the mother of the Singing Ridge nether drakes.\n\nIs that what you are here to tell me?", completion = "No?  You slew Dreadwing?  Perhaps I was wrong about you, {class}.\n\nPerhaps.\n\nStill, you have slain the chiefs of the three greatest threats that we face.  That is something to be proud of.\n\nI offer you a token of my appreciation, but don't let it go to your head.  You still do not fully understand what it is to be Mok'Nathal, and we may still have need to call upon your skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[10846] = { id = 10846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the Mok'Nathal", description = "<Leoroxx looks you in the eye with the kind of stare that chills your soul.>\n\nYou come to the Mok'Nathal, but you do not understand us.  You do not understand our struggle to survive.\n\nIf you would understand us, then you will have to endure a taste of that struggle.\n\nTo the south are the Vekh'nir arakkoa.  They have enslaved a group of ogres in the caverns known as Trogma's Claim and their leader, Vekh is in there.\n\nSlay him!", sourceObjective = "Slay Vekh, leader of the Vekh'nir arakkoa.", progress = "We have many enemies.  Some we have chosen, and some, such as the Vehk'nir, we have not.\n\nRegardless, we shall slay all of their chieftains until none stand before us.", completion = "The Vekh'nir are the least of our adversaries.\n\nSo, you know how to slay an overgrown bird.  This does not make you a true warrior.  This does not give you a full understanding of our ways.\n\nBut it's a start.", sourceObjectiveStatus = "unverified-source-field" }
quests[10847] = { id = 10847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes of Skettis", description = "Doom harkens from the cliffs of Skettis.\n\nMy people, the arakkoa, face a fate shrouded in unspeakable evil. Too often have we abused dark magic for wrongdoing. Through A'dal I have learned of the Light and of redemption.\n\nTerokk watches his colonies from Skettis through orbs enchanted by the black art. Steal these Eyes from Veil Reskk and Veil Shienor in northern Terokkar. Let me see what Terokk sees. Let me look through the eyes of Skettis.", sourceObjective = "Bring the Eye of Reskk and the Eye of Shienor to Rilak the Redeemed in the Lower City section of Shattrath City.", progress = "You have returned, {class}. What news do you bring?", completion = "Your bravery should be commended. The guardians of Skettis do not part with their belongings willingly.\n\nBut heroics of the past are of little consequence now. We shall see if such bravery continues to persist in the future, for Terokk's gaze fixates on the south.\n\nThese Eyes are all seeing.", sourceObjectiveStatus = "unverified-source-field" }
quests[10848] = { id = 10848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veil Rhaze: Unliving Evil", description = "Veil Rhaze was a particularly wicked colony of Skettis.\n\nDespite the village's eradication by the Auchindoun disaster, Terokk's influence remained in the maligned spirits there. Travel west to Veil Rhaze and slay those murderous wretches. You'll find them to the west of the Shadow Tomb, on the border of Bone Wastes and Terokkar Forest.\n\nThis will be our first blow against Terokk and the guardians of Skettis.", sourceObjective = "Kill 4 Deathtalon Spirits, 4 Screeching Spirits and 2 Spirit Ravens and return to Kirrik the Awakened at the Refugee Caravan.", progress = "Evil grows in Veil Rhaze. Put it down, {race}.", completion = "Those foul spirits deserved to die. The death they would have wrought on others is reason enough.\n\nWe cannot hope to redeem those in Terokk's grasp. But we shall deliver them a devastating blow in the name of the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[10849] = { id = 10849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Kirrik", description = "Other arakkoa took part in the betrayal of Terokk.\n\nKirrik recognized Terokk as a charlatan, not a prophet. The only prophecy Terokk envisioned was the doom borne of his own bidding.\n\nIt was Kirrik who led us bravely from Skettis. After our pilgrimage to Shattrath, Kirrik traveled to the colonies in search of others.\n\nThis missive tells of what the Eyes have seen. Kirrik must be told! Follow the road south out of Shattrath to the Bone Wastes and look for the caravan.", sourceObjective = "Take Rilak's Missive to Kirrik the Awakened at the Refugee Caravan in the Bone Wastes.", progress = "You have traveled far and bear news for me.", completion = "Rilak's tale is grim, traveler. As you can see from the state of the caravan, there is much sorrow and darkness in the forest of Terokk these days.", sourceObjectiveStatus = "unverified-source-field" }
quests[10850] = { id = 10850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nether Gas In a Fel Fire Engine", progress = "You uncover an opening through which fuel is loaded into the fel reaver.", completion = "The fel reaver's engine begins to rumble and sputter as you supply it with the incorrect fuel." }
quests[10851] = { id = 10851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Totems of My Enemy", sourceObjective = "Collect 5 Bladespire Totems.", progress = "Have you gone to Bladespire Outpost and taken their totems from them?", completion = "This looks like a good assortment.  We should be able to find a respectful use for one or two of them.\n\nIn fact, I have an idea for how to do just that!", sourceObjectiveStatus = "unverified-source-field" }
quests[10852] = { id = 10852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Friends", description = "We broke down here because some guys came in the night and made a lot of noise.  It was scary.  I don't know when we are going to get moving again.  \n\nSome of my friends are missing though.  I don't know where they are.  I think those scary bird men took them away to the northwest.  They probably are all locked up in cages and stuff.  If you find them that would be great.  I'm kind of worried about them.", sourceObjective = "Ethan wants you to find 12 of his missing friends in Veil Skith and then return to him at the Refugee Caravan.", progress = "I'm bored, there's nobody to play with.  Have you found my friends?", completion = "You found all my friends!  Now I have someone to play with.  Thank you, Mister {name}.  \n\nSince I have kids to play with maybe you would like one of my toys?  That way you have something to play with too.", sourceObjectiveStatus = "unverified-source-field" }
quests[10853] = { id = 10853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit Calling", description = "The spirits of the nether drakes in the Singing Ridge are in need of liberation.\n\nThe nether drakes were not always nether drakes.  They used to be black drakes.\n\nBut then, with the destruction of this world, a wave of nether energy washed over everything and had the side-effect of changing the drakeling eggs.\n\nNow they are all twisted versions of their former selves.  We must help them to find peace.\n\nDo this by slaying a drake near to the spirit calling totem, and then take its spirit from it.", sourceObjective = "Use the Spirit Calling Totems to collect 8 Lesser Nether Drake Spirits.", progress = "The drakes of the Singing Ridge may pose a threat to us, but I think they are majestic creatures.\n\nOr, at least they were.  I hope that you will be able to save their spirits.\n\nAnd if you are in need of more totems, I have a few to spare.", completion = "You have done a good thing this day, {class}.  The spirits of the drakes will truly sing again now that they have been freed.  And the residual part of their spirits that they leave behind are powerful medicine, too.\n\nI wonder, are you up for a journey to the north?  There is something that I am curious about concerning the activities of the ethereal.\n\nI sense a great deal of pain coming from their direction.", sourceObjectiveStatus = "unverified-source-field" }
quests[10854] = { id = 10854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Force of Neltharaku", description = "Take this enchanted nethervine crystal and make your way back to Dragonmaw Fortress. Once there, seek out the enslaved drakes and invoke the magic of the nethervine crystal. My own energies will pour forth, causing the drakes to break free from the bond of their captors. When you see that the drake has broken free, help it defeat its captor! It will most assuredly be weak from the imprisonment.\n\nRelease all that you can find and return to me, {name}.", sourceObjective = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to free 5 Enslaved Netherwing Drakes.", progress = "Waste no time, we have much work to do!", completion = "<Neltharaku laughs.>\n\nThe orcs must have been shocked to see the drakes turn on them in such a manner. Well done, {name}. Perhaps you truly are the hero of our flight.", sourceObjectiveStatus = "unverified-source-field" }
quests[10855] = { id = 10855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Reavers, No Thanks!", description = "Ah, yes - the fel reaver!  Certainly the Legion's most terrible mechanical creation.  There are no less than three of these abominations aimed at the Stormspire.\n\nFortunately for us, they are not active yet.  This affords us the possibility of dealing with them through sabotage instead of brute force.\n\nObtain condensed nether gas from the gan'arg at Forge Base: Oblivion and fill a nearby fel reaver's fuel tank with it.  I've a feeling its engine won't handle it too well.", sourceObjective = "Obtain 5 Condensed Nether Gas from Gan'arg Mekgineers at Forge Base: Oblivion, northwest of the Stormspire, and load them into a nearby Inactive Fel Reaver. Return to Nether-Stalker Nauthis after you've completed this task.", completion = "That is excellent news, {name}.  Now that we know how to deal with these, I can have hirelings sabotage any remaining reavers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10856] = { id = 10856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Defense", description = "Brave acts of industrial sabotage will only get us so far, {name}.  Just as Forge Base: Oblivion serves as an assembly site for Fel Reavers, Forge Base: Gehenna serves as a staging ground for their army as it is where the majority of the Legion's teleportation devices are located.\n\nI want you to go in there and put a dent in their numbers.  They must have a full regiment of wrathbringers by now and we just can't allow that.", sourceObjective = "Nether-Stalker Nauthis wants you to slay 12 Wrathbringers at Forge Base: Gehenna, north of the Stormspire.", progress = "How goes it?  Did you get a chance to show the Legion a lesson or two?", completion = "Nice work, {name}.  Keep it up and I'll put in a good word with the Nexus-Prince.", sourceObjectiveStatus = "unverified-source-field" }
quests[10857] = { id = 10857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teleport This!", description = "As fun as killing demons might be, it does us little good when the Legion can keep using its teleporters to replace anything we kill.\n\nUnfortunately, I don't have any high-powered explosives handy... but the mo'arg that maintain the teleporters do.\n\nTake this rod... I've tuned its powers to interfere with mo'arg brain frequencies.  Return to Forge Base: Gehenna and use it on any mo'arg you see.  You won't have long, but you'll be able to use their demolition charges on the nearby teleporters.", sourceObjective = "Nether-Stalker Nauthis wants you to use the Mental Interference Rod on the Mo'arg at Forge Base: Gehenna and use their Detonate Teleporter ability on the three teleporters in the forge camp.", progress = "Is it done then?  Are the teleporters shut down?", completion = "Thanks to you, {name}, I'll breathe a little easier.  Figure of speech, of course!\n\nI suppose you'll want some form of reward now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10858] = { id = 10858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karynaku", description = "It shames me to ask for your assistance once more, {name}, but you are my flight's only hope. Without my mate, the netherwing brood may die out completely.\n\nMake your way to the top of Dragonmaw Fortress and find Karynaku.\n\nWe will be flying overhead. Should a break appear in their defenses, the might of the netherwing will swoop down to assist you.", sourceObjective = "Seek out Karynaku at Dragonmaw Fortress.", completion = "It is the chains. They sap my power. The only way is to get the key from Zuluhed and unbind me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10859] = { id = 10859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather the Orbs", description = "The Razaani ethereals have strange devices that emit small, pink floating light orbs.  They remind me of souls.\n\nThey are not to be confused with the large yellow balls that break free of the ethereal when they die, these are something else entirely.\n\nI'd like for you to head north to Razaan's Landing and drop some totems, which will attract the pink light orbs.\n\nBring them back to me so that I might determine exactly what they are.", sourceObjective = "Use the Orb Collecting Totem to collect 15 Razaani Light Orbs.", progress = "Have you collected all of the Razaani Light Orbs that are needed?", completion = "Something does not feel right.\n\nPlease, {name}, hand me the totem.  I must examine those orbs!", sourceObjectiveStatus = "unverified-source-field" }
quests[10860] = { id = 10860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'Nathal Treats", description = "Hungry, {race}?  The Great Spirit helps those that help themselves.  If you want to earn a meal, I suggest that you listen up, because Braagor there isn't going to give you anything for free, nor as tasty!\n\nThe raptors and scalewings of Razor Ridge and the Scalewing Shelf have everything that's needed for two of the most delicious dishes you'll ever taste.  Bring me their raptor ribs and serpent flesh, and I'll make some of each for you.\n\nI may even teach you how to cook them up for yourself, if you hurry.", sourceObjective = "Collect 3 Raptor Ribs and 3 Serpent Flesh.", progress = "Have all of the ingredients yet?  Talking about it with you has made my mouth water!", completion = "Mmm, I can taste them already.  Quickly, hand over those parts... I'm going to get them diced up and onto the fire!\n\nLuckily for you, this stuff keeps, and I mean for a long time!  So, take these, and I suppose you can have the recipes as well for being so kind as to restock my larder.", sourceObjectiveStatus = "unverified-source-field" }
quests[10861] = { id = 10861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veil Lithic: Preemptive Strike", description = "In the wretched colony to the southwest known as Veil Lithic, Terokk's minions are attempting to befoul their avian brethren before they hatch. The dark sorcerers of Lithic encase eggs in a shadowy curse. When the hatchlings emerge, they mindlessly serve Terrok.\n\nTravel to Veil Lithic and prematurely break the eggs before the curse has time to seep in. Even if you are too late, you can put down the tainted ones.\n\nRemember, the Light shines brightest in the darkness.", sourceObjective = "Break the cursed eggs in Veil Lithic. Redeem 3 Hatchlings and slay 3 Malevolent Hatchlings before returning to Kirrik the Awakened at the Refugee Caravan.", progress = "Have you done your bidding? Quash the evil before it is too late!", completion = "It is grim work toiling with someone's hatchlings, yet ignoring the brewing evil would be a bleak proposition as well. You have done well.  A'dal's favor shines upon your heart.", sourceObjectiveStatus = "unverified-source-field" }
quests[10862] = { id = 10862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrender to the Horde", description = "The cowardly arakkoa attack us daily.  They ambush our hunters and sometimes even raid inside our walls.  We kill them when we can, but their magic is strong and they often escape our warbands.  \n\nI have learned that some arakkoa claim to be friendly with the Horde.  They live in Shattrath City to the northwest.  Rilak the Redeemed is their leader.  Search for him in the Lower City, and when you find him, demand his surrender.", sourceObjective = "Rokag wants you to seek out Rilak the Redeemed in the Lower City section of Shattrath City and demand that he and his people surrender to the Horde.", completion = "Your people are angry but there is little I can do.  Some of us have been touched by the power of the naaru and we are forever changed.  Those of us who remain in the wild are as we have always been.", sourceObjectiveStatus = "unverified-source-field" }
quests[10863] = { id = 10863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Arakkoa", description = "Out here on the frontier we have to deal with the arakkoa every day.  They strike at us when they please, raiding our supply lines and killing our scouts.  \n\nYet we know very little about these enigmatic creatures.  I have received news that northwest of here in Shattrath City there are arakkoa who are not hostile.  They might be willing to share the secrets of their race.  \n\nRilak the Redeemed is their leader.  He resides in the northern part of the Lower City.", sourceObjective = "Lady Dena Kennedy wants you to seek out Rilak the Redeemed in the Lower City section of Shattrath City and find out what secrets he will share of the Arakkoa.", completion = "You are wise to find me.  There is much that I can show you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10864] = { id = 10864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burden of Souls", description = "I have a device, the Demoniac Scryer, that can analyze fel magic.  I would have you use the Scryer, but first... you must appease it.  The Scryer, you see, has trapped within it a creature of vast intelligence and its needs are, shall we say, quite eccentric.\n\nTo appease the Scryer, you must kill orcs.  Specifically, they must be Shattered Hand orcs -- the Scryer demands their souls.\n\nReturn to me when the souls are reaped.  You will find the orcs north, and south, and surrounding... Hellfire Citadel.", sourceObjective = "Kill 20 Shattered Hand orcs, then return to Apothecary Antonivich in Thrallmar.", progress = "The Demoniac Scryer is not yet appeased, {name}.  Return to me after you have reaped the souls of Shattered Hand orcs.", completion = "Well done, {name}.  Your soul is burdened with many deaths... and the Demonaic Scryer will now perform its duties for you.\n\nLet us hope you are ready for the coming trial...", sourceObjectiveStatus = "unverified-source-field" }
quests[10865] = { id = 10865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inform Leoroxx!", description = "Quickly, you must inform Leoroxx of what is transpiring up at Razaan's Landing!\n\nThose orbs were comprised of souls, some of them Mok'Nathal!", sourceObjective = "Speak with Leoroxx about what the Razaani ethereal are up to. He can be found at Mok'Nathal Village in the Blade's Edge Mountains.", completion = "What you say, is it even possible?  What am I saying?  Of course it is, if the spiritcallers say so.\n\nRemember before when I said that we might need your further assistance?  It would seem that I can tell the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[10866] = { id = 10866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed the Whacked", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", sourceObjective = "Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku.", progress = "<Karynaku groans.>", completion = "I am free! You have saved us, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10867] = { id = 10867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Can Be Only One Response", description = "There can be only one response to this... this, DEFILEMENT of the souls of our ancestors!\n\n{name}, if you would aid us to restore the souls of our honored dead to their rightful place, go back to Razaan's Landing.\n\nGo back up there and kill the razaani until their leader, Nexus-Prince Razaan shows his cowardly face.  Kill him and get those souls back, and then give them over to Spiritcaller Dohgar!", sourceObjective = "Collect the Collection of Souls.", progress = "Have you done it?  Are the souls of our ancestors safely recovered from the evil of the ethereals?", completion = "Good that the ethereal filth and their leader are dead.  I wish a thousand plagues upon their brethren!\n\nYou are to be rewarded for you actions on behalf of all of the Mok'Nathal, {name}!  You are truly one of our heroes.\n\nLet us now release the souls of our ancestors to the cleansing fire.", sourceObjectiveStatus = "unverified-source-field" }
quests[10868] = { id = 10868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arakkoa War Path", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could charge out to meet them in numbers.  They use their summoning circles to rescue their warriors from certain death but they cannot run from us if we attack their homes.  Veil Reskk and Veil Shienor lie to the north and northeast.  \n\nFind these arakkoa nests and kill as many as you can.", sourceObjective = "Advisor Faila asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to her in Stonebreaker Hold.", completion = "Well done {class}.  The arakkoa have learned to fear the might of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10869] = { id = 10869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thin the Flock", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could marshal our soldiers.  \n\nVeil Reskk and Veil Shienor lie to the north and northwest.  Find these arakkoa nests and kill as many as you can.  They may not fear us, but at least we can thin their numbers.", sourceObjective = "Lieutenant Gravelhammer asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to him in Allerian Stronghold.", completion = "Well done {class}.  The arakkoa have learned to fear the might of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10870] = { id = 10870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ally of the Netherwing", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", sourceObjective = "Let Karynaku return you to Mordenai in the Netherwing Fields.", completion = "You have proven yourself as an ally of the Netherwing. My mother is free and my brothers and sisters are saved!\n\nPerhaps someday, we will call for you again. When that day comes, know that you will be welcomed with open arms - a brother to the Netherwing Dragonflight.", sourceObjectiveStatus = "unverified-source-field" }
quests[10871] = { id = 10871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ally of the Netherwing", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", sourceObjective = "Let Karynaku return you to Mordenai in the Netherwing Fields.", completion = "You have proven yourself as an ally of the Netherwing. My mother is free and my brothers and sisters are saved!\n\nPerhaps someday, we will call for you again. When that day comes, know that you will be welcomed with open arms - a brother to the Netherwing Dragonflight.", sourceObjectiveStatus = "unverified-source-field" }
quests[10872] = { id = 10872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed the Whacked", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", sourceObjective = "Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku.", progress = "<Karynaku groans.>", completion = "I am free! You have saved us, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10873] = { id = 10873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taken in the Night", description = "Our small outpost is under constant attack. Several nights ago, we were raided by the spiders of Netherweb Ridge, on the southeastern edge of the Bone Wastes. They poisoned many of our people, wrapped them in webs and carried them away. Some of our warriors took up arms and with little preparation pursued the spiders.\n\nWe have not seen the captives or our hunting parties since. We hope that some may still be alive, perhaps imprisoned by the spiders.  Our numbers are few. Will you search for our people?", sourceObjective = "Scout Navrin wants you to travel to the Netherweb Ridge and free 6 Webbed Sha'tar Warriors and then return to him at Sha'tari Base Camp.", progress = "Did you find our missing people?", completion = "You saved so many.  I didn't think we would ever see them again.  We cannot thank you enough, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10874] = { id = 10874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veil Shalas: Signal Fires", description = "Terokk's perch, Skettis, looms above the Bone Wastes to the east. At the base of Skettis lies Veil Shalas, the most formidable of Terokk's colonies. It is through the stronghold of Veil Shalas that Terokk's forward sages wage war against the Light.\n\nThe evil-doers of Shalas communicate with their master using a complex system of magical signal fires. Travel to the east, {race}, and extinguish the fires. Once Veil Shalas is silenced, we can begin to plot the fall of Skettis.\n\nBut I get ahead of myself.", sourceObjective = "Kirrik the Awakened at the Refugee Caravan wants you to extinguish the four signal fires of Veil Shalas.", progress = "Veil Shalas must be silenced!", completion = "We witnessed the cursed smoke rise from here. You are most brave, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10875] = { id = 10875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Nazgrel", description = "{name}, during your foray with the Demoniac Scryer, I sent word of your exploits against the fel orcs.  Nazgrel, our illustrious leader in Thrallmar, wishes to speak with you.  I believe he has a bloody mission in mind...", sourceObjective = "Speak with Nazgrel at Thrallmar in Hellfire Peninsula.", completion = "It is good to hear of all your moves against the fel orcs, {name}.  The apothecaries have spent much time and resources studying the cause of their corruption, and although such information in invaluable... my orc blood burns to strike a severe blow against these betrayers!\n\nListen close, and I will explain my task...", sourceObjectiveStatus = "unverified-source-field" }
quests[10876] = { id = 10876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Foot of the Citadel", description = "Force-Commander Gorax is training Shattered Hand captains at the base of Hellfire Citadel, honing them to a bloody razor's edge.  You must kill him, {name}, for his loss would be a mighty blow to the fel orcs.\n\nHowever, that is not all you must do.\n\nTake this banner.  Place it atop Gorax's corpse.  Gorax's commander, the Hand of Kargath, must answer your challenge if he has even a drop of true orc blood within him!\n\nHis head, the head of the hand of Kargath, is what I seek.", sourceObjective = "Kill Force-Commander Gorax, place the Challenge From the Horde upon his corpse, kill The Hand of Kargath, and then bring the Head of the Hand of Kargath to Nazgrel in Thrallmar.", progress = "Have you faced the Hand of Kargath, {name}?", completion = "You have done a great deed, {name}.  The fel orcs are a shame to all true orcs.  If we have one fear, it is the fear of  succumbing to demonic corruption once again.  So you see, our war against the fel orcs is more than merely a battle with fierce foes -- it is also a battle within ourselves.\n\nAnd with strength, strength you have shown time again, it is a battle we will win.", sourceObjectiveStatus = "unverified-source-field" }
quests[10877] = { id = 10877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dread Relic", description = "Long ago a caravan went to Auchindoun with a mission to take a Dread Relic from the ancient tombs beneath the necropolis. They fled, but the relic was their undoing.  The relic is evil and it summons evil when touched.   Their caravan was destroyed somewhere to the east. \n\nThis dark artifact is the key to a terrible plan to defeat Teribus the Cursed, a creature that flies over the Bone Wastes.  Help me if you wish, but your life and even your soul will be at risk.", sourceObjective = "Oakun wants you to travel east to the Derelict Caravan to recover the Dread Relic. Return to Oakun when the task is complete.", progress = "Do you have the Dread Relic?  We must have it.", completion = "It is incredible that you succeeded.  The Dread Relic is far more powerful than I feared. Only a mighty hero could have survived the long journey back carrying such blasphemous evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[10878] = { id = 10878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before Darkness Falls", description = "After our caravan fell prey to an attack by Shadow Council cabal cultists, scouts were sent to Shattrath to call for help.  The guards think we're safe for now, but they underestimate these madmen.\n\nI, for one, am not looking forward to having my throat slit by some cabal initiate in the middle of the night.  Do us all a favor and take the fight to them, before they come to us.\n\nYou will find our attackers south of here, at Auchindoun's northern entrance.", sourceObjective = "Mekeda at the Refugee Caravan wants you to kill 8 Cabal Skirmishers, 4 Cabal Spell-Weavers and 2 Cabal Initiates.", progress = "Have you done what I asked of you, {name}?  I fear for our lives.", completion = "I can breath a sigh of relief for now, {name}.  The Shadow Council will be held off for the time being.\n\nThey are murderers and cowards and your display of courage will keep them at bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[10879] = { id = 10879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skettis Offensive", description = "Skettis has waged war on us! Have you gathered enough strength to help with Shattrath's defense?\n\nHold off the attackers!", sourceObjective = "Hold off the attackers and speak with Rilak the Redeemed.", progress = "This is no time for idle chatter, {name}. We're under attack! Hold off the invaders!", completion = "I applaud your prowess in combat, {class}. You have proven yourself to be a true defender of the Light. May A'dal's blessing shine upon your darkest hours.\n\nBut look far into the horizon. Dark skies loom above Skettis. Terokk is undoubtedly plotting his next move. Shattrath is safe for now. But only tomorrow knows what terror will descend upon us.", sourceObjectiveStatus = "unverified-source-field" }
quests[10880] = { id = 10880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cabal Orders", description = "This message bears a dark seal and though the language seems somewhat familiar, it appears to be encoded.\n\nPerhaps someone at the Refugee Caravan will know something about it.", sourceObjective = "Bring the Cabal Orders to Mekeda at the Refugee Caravan in the Bone Wastes.", progress = "You wish to show me something, {name}?", completion = "Ah, yes... this was written in a basic form of the shadow cypher.  My knowledge of it is not perfect but it should suffice to translate this.\n\nYou learn much about unsavory subjects when you live among outcasts and refugees in the Lower City.", sourceObjectiveStatus = "unverified-source-field" }
quests[10881] = { id = 10881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Tomb", description = "Many believe it was the Shadow Council that caused the explosion that tore Auchindoun apart.  It is rumored they awoke a great evil inside.\n\nIf that is true, then that evil must have turned against them.  According to these orders, part of the Shadow Council is fleeing Auchindoun.  They are using the Shadow Tomb to store powerful artifacts from Auchindoun.\n\nThree of these are sacred, for they belonged to the powerful patriarchs Arunen, K'alen and Atalor.  I must ask you to retrieve them.", sourceObjective = "Go into the Shadow Tomb, west of the Refugee Caravan and retrieve the Drape of Arunen, the Gavel of K'alen and the Scroll of Atalor. Return to Mekeda at the Refugee Caravan after you've completed this task.", progress = "Have you retrieved the relics, {name}?  We cannot allow the Shadow Council to use their power for dark purposes.", completion = "The Light might have forgotten me, but I have not forgotten the Light.  These relics were once very sacred to my people.\n\nAllowing the Shadow Council to use their power for evil is... unthinkable!", sourceObjectiveStatus = "unverified-source-field" }
quests[10882] = { id = 10882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbinger of Doom", description = "<A discordant note can be detected in A'dal's 'voice'.>\n\nPrince Kael'thas has chosen his warden poorly, and now the entities that we kept locked up within the Arcatraz are breaking free.\n\nOne in particular, a servant of the Old Gods known as Harbinger Skyriss, seeks to usher in his masters' vision of conquering all of the worlds in the universe.\n\n{name}, you must not allow him to escape.  Return to Tempest Keep, enter the Arcatraz, and slay Harbinger Skyriss before it is too late!", sourceObjective = "You have been tasked to go to Tempest Keep's Arcatraz satellite and slay Harbinger Skyriss. Return to A'dal at the Terrace of Light in Shattrath City after you have done so.", progress = "<A'dal focuses his attention upon you, his gaze almost unbearable.>\n\n{name}, perhaps you do not understand the magnitude of your mission?  There is no time to waste... gather yourself a group of compatriots and enter the Arcatraz.\n\nPut an end to Harbinger Skyriss.", completion = "<The crystalline timber of A'dal's voice carries a more tranquil melody within your mind than the last time the two of you spoke.>\n\nOnce again you have proven your mettle.  Had Harbinger Skyriss broken free, countless thousands would have perished in the ensuing conflict, just as happened with another servant of the Old Gods, Skeram, on your world of Azeroth.\n\n{name}, what I have to offer in return may seem a pittance in comparison, but know that it comes with the everlasting gratitude of the Sha'tar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10883] = { id = 10883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tempest Key", description = "You have proven yourself capable of great feats, {name}. Your discovery of the Cipher of Damnation and Kael'Thas' involvement is most important to our cause. Should Kael use the cipher, what little is left of this world may collapse.\n\nA'dal is convinced that Kael must be stopped and now seeks adventurers willing to undergo trials. Those that prove their strength will be granted favor by the naaru.\n\n<Khadgar nods.>\n\nA'dal awaits...", sourceObjective = "Speak with A'dal in Shattrath City.", completion = "Tempest Keep is a naaru creation, mortal. Access to the vessel has always been within our power to grant. A return to Tempest Keep, though, had been deemed unnecessary. A point of pride for a mortal race, perhaps, but naaru invest little in such things.\n\nWe go now because we must. Kael'thas cannot be allowed to utter the words of damnation.\n\nWhile the way is open, only a fool would enter unproven. Do not underestimate the purpose of the trials, mortal.", sourceObjectiveStatus = "unverified-source-field" }
quests[10884] = { id = 10884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Mercy", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nWithin the Shattered Halls of Hellfire Citadel are three of your people. They are held there by the merciless one, Kargath Bladefist. He seeks to execute them as a sign of his virility and power. You must save these prisoners before such an atrocity can come to pass. As proof of deed, bring me the unused axe of the executioner. It must not have a drop of blood on its blade!", sourceObjective = "A'dal in Shattrath City wants you to recover the Unused Axe of the Executioner from the Shattered Halls of Hellfire Citadel.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "<A'dal greets you.>", completion = "Well done, {name}. You have passed the trial of mercy.", sourceObjectiveStatus = "unverified-source-field" }
quests[10885] = { id = 10885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Strength", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nThe trial of strength is divided in two. You must destroy the leader of the Coilfang Steamvaults, Warlord Kalithresh, and bring me his trident. Slay the extra-planar being known as Murmur, in the Shadow Labyrinth of Auchindoun, and bring me his essence.\n\nDo this and you will have passed the trial of strength.", sourceObjective = "A'dal in Shattrath City wants you to recover Kalithresh's Trident and Murmur's Essence.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "<A'dal greets you.>", completion = "Well done, {name}. You have passed the trial of strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[10886] = { id = 10886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Tenacity", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nIn our travels we have encountered many dangerous beings. Some of these beings we incarcerated and placed in what is now known as the Arcatraz of Tempest Keep.\n\nThere is one prisoner, however, that is a victim of circumstance. A stowaway who was in the wrong naaru vessel at the wrong time.\n\nVenture to the Arcatraz and rescue the gnome, Millhouse Manastorm. Ensure his survival.", sourceObjective = "A'dal in Shattrath City wants you to rescue Millhouse Manastorm from the Arcatraz of Tempest Keep.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "<A'dal greets you.>", completion = "Well done, {name}. You have passed the trial of tenacity.", sourceObjectiveStatus = "unverified-source-field" }
quests[10887] = { id = 10887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escaping the Tomb", description = "I appreciate your help, {name}.  I was certain I was going to be killed.\n\nLet's get out of here with a hurry.  It won't be long before more cultists come after us.", sourceObjective = "Help Akuno find his way to the Refugee Caravan. Speak to Mekeda after you've completed this quest.", completion = "You rescued Akuno, a dear friend of mine.  For this I am in your debt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10888] = { id = 10888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Magtheridon", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", sourceObjective = "A'dal in Shattrath City wants you to slay Magtheridon.", progress = "<A'dal greets you.>", completion = "You have proven yourself as a being of great power. The naaru approve...", sourceObjectiveStatus = "unverified-source-field" }
quests[10889] = { id = 10889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Shattrath", description = "Your actions, while brave, will surely rouse a vindictive response from Terokk.\n\nHurry to Shattrath. Send word to Rilak!", sourceObjective = "Travel to Shattrath City and speak with Rilak the Redeemed in the Lower City.", completion = "The guardians of Skettis grow restless from their perch. Shattrath is in trouble. We will surely feel the brunt of Terokk's revenge.\n\nMuster a defense party quickly! Speak with Defender Grashna and let him know you are ready to bear arms against our attackers!", sourceObjectiveStatus = "unverified-source-field" }
quests[10891] = { id = 10891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Armor", description = "There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?", sourceObjective = "Speak with Derotain Mudsipper at Gadgetzan in Tanaris.", completion = "Of course I'll teach you how to make imperial plate armor! It might cost you a bit of gold... in the form of thorium bars!", sourceObjectiveStatus = "unverified-source-field" }
quests[10892] = { id = 10892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Armor", description = "There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?", sourceObjective = "Speak with Derotain Mudsipper at Gadgetzan in Tanaris.", completion = "Of course I'll teach you how to make imperial plate armor! It might cost you a bit of gold... in the form of thorium bars!", sourceObjectiveStatus = "unverified-source-field" }
quests[10893] = { id = 10893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Longtail is the Lynchpin", description = "With the Blackwing wyrmcultists massing in the tunnel, we're hard pressed to deal with the situation.  Quite frankly, they have the numbers.\n\nAnd while we've been able to take care of any of their people that get too close, the fact remains that if they attack in earnest, we're going to be overrun.\n\nThe situation calls for someone to get through to the other end of the tunnel, and take out their leader, Draaca Longtail.  Up for some fun?", sourceObjective = "Slay Draaca Longtail, the leader of the wyrmcultists in the Wyrmskull Tunnel.", progress = "Is she dead?\n\n{name}, if we're to have a fighting chance here, we need you to sow confusion into their ranks by killing Draaca Longtail!", completion = "With Draaca out of the picture, we should be able to take advantage of the situation.  They'll be in-fighting over who should be in charge, and that will relieve some of the pressure.\n\nThat is, unless the overseer mentioned in that note you gave me comes to take her place.\n\nLet's see if you can do something to make sure that never happens!", sourceObjectiveStatus = "unverified-source-field" }
quests[10894] = { id = 10894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wyrmskull Watcher", description = "Hmm, I'm not certain what we should do.  I'm not much of a military planner.\n\nWatcher Moonshade will know what to do.  He's heading up our defensive efforts at the Wyrmskull Tunnel to the west at the end of Wyrmskull Bridge.  We have a force out there just in case the cultists try anything funny.\n\nPlease, take the note to him with all due haste.", sourceObjective = "Deliver the Meeting Note to Watcher Moonshade at the entrance of the Wyrmskull Tunnel in the Blade's Edge Mountains.", progress = "How can I help you?  You bring news from Evergrove?", completion = "It's as I thought, and that's not good!\n\nI've got an idea for how to help you, but first, I was wondering if you might help us out?\n\nYou scratch my back, I'll scratch yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[10895] = { id = 10895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor Must Burn!", description = "It's time to strike Zeth'Gor from the air!  Our gryphon riders are ready for a sortie, {name}.  But they need someone on the ground to direct their fire.  Are you ready for a covert mission?\n\nTake these smoke beacons into Zeth'Gor, the Bleeding Hollow stronghold to the west.  They have four guard towers: one near their northern wall, one near their southern wall, one near their forge and another nestled in their foothills.  Place a beacon underneath each of the towers and we'll fly in and bomb them!", sourceObjective = "Use the smoke beacon at each of Zeth'Gor's towers, and then return to Wing Commander Dabir'ee at Expedition Point.", progress = "Time is crucial, {name}.  We need those guard towers burned!", completion = "I could see the smoke and flames from here!  Good job, {name}!  You received more than a few words of praise from our gryphon riders -- what you just did took a lot of guts...", sourceObjectiveStatus = "unverified-source-field" }
quests[10896] = { id = 10896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Infested Protectors", description = "The trees of this land are ravaged by the power that was unleashed from Auchindoun.  The foul magic that was unleashed blasted the land into the wastes you see all around.  The trees that survived are now infested with wretched wood mites that crawl under their bark and gnaw at their flesh.  \n\nRotting forest-ragers and infested root-walkers are breeding grounds for the mites.  They are found along the edge of the wood to the east.  Destroy these creatures and then kill the mites that flee their husks.", sourceObjective = "Lakotae wants you to kill 25 Wood Mites and then return to him at the Refugee Caravan. The mites can be found living inside the bodies of Rotting Forest-Ragers and Infested Root-Walkers.", progress = "Have you destroyed the worst of the infestations?", completion = "You have done much to help Terokkar Forest, {name}.  With the worst of the mite colonies destroyed we may yet be able to reclaim this wasted land.", sourceObjectiveStatus = "unverified-source-field" }
quests[10897] = { id = 10897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Potions", description = "As you know, plants have properties that allow alchemists to re-energize and reinvigorate others through potions.\n\nMy familiarity with the plants of Outland allows me to teach alchemists how to make the most out of them.  If you're interested in expanding your knowledge of potions, I have but one task to ask of you.\n\nHigh Botanist Freywinn in Tempest Keep is rumored to have written a comprehensive botany guide.  Bring it to me along with samples of your work and I'll teach you the knowledge you seek.", sourceObjective = "Lauranna Thar'well wants you to go to the Botanica in Tempest Keep and retrieve the Botanist's Field Guide from High Botanist Freywinn. In addition she also wants you to bring her 5 Super Healing Potions, 5 Super Mana Potions and 5 Major Dreamless Sleep Potions.\n\n*WARNING!* You can only select one alchemy specialization.", progress = "Are you sure about this, {name}?  Specializing in potions will prevent you from pursuing other specializations.", completion = "Excellent!  It looks like you're eager to learn, so let's get to it.  I will teach you how to make the most out of the plants you use in your alchemical potions.\n\nYou will find that you can make herbs go a really long way if you know what you're doing.  Sometimes you will be able to make two potion with materials you initially judged necessary for just one.", sourceObjectiveStatus = "unverified-source-field" }
quests[10898] = { id = 10898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skywing", description = "Skywing flutters around you.\n\nYou get the feeling he wants you to follow him.", sourceObjective = "Escort Skywing and report to Rilak the Redeemed in Shattrath City.", completion = "Alas, poor Skywing was under the dreaded curse of Luanga the Imprisoner!\n\nSkywing traveled to Veil Shalas to attempt to sway others in seeing the way of the Light. They didn't take lightly to his actions, especially sitting on the doorstep of Skettis.\n\nLuanga was one of Terokk's most feared agents. You have done well by freeing Skywing! I thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10899] = { id = 10899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Transmutation", description = "Any alchemist will tell you that matter is malleable, any substance can be transformed into another - but nothing is really created or destroyed.\n\nA true master of transmutation can learn to overcome this limitation - and I can teach you how to obtain this mastery!\n\nAs a prospective transmuter you're undoubtedly familiar with primal might - the combination of the material representation of all primal forces.  Show me proof of your transmuting prowess and I will share my knowledge with you.", sourceObjective = "Zarevhi at the Stormspire in Netherstorm wants you to bring him 4 Primal Mights.\n\n*WARNING!* You can only select one alchemy specialization.", progress = "Are you sure you want to become a master transmuter?  If you specialize in this field you will find it impossible to specialize in potions or elixirs.", completion = "Excellent work, {name}!  These transmutations are perfect in every way!\n\nI will now teach you the manner in which the alchemical transmutation process can conjure matter out of thin air!  Make good use of your knowledge, master transmuter.\n\nNow, if you'll excuse me, I have to go see a buyer interested in primal might.", sourceObjectiveStatus = "unverified-source-field" }
quests[10900] = { id = 10900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Vashj", sourceObjective = "Burn it down, {race}. Burn it all down! They deserve nothing! Do you hear me! NOTHING! They must pay for what they have done. For what they continue to do.\n\nI would kill Vashj myself if I could break free of these damned bindings.\n\nOr maybe you seek to do the work of Neptulon? Her death serves both of us, soft-skin. Will you assist me in forming the sacred cudgel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10901] = { id = 10901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cudgel of Kar'desh", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!", sourceObjective = "Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet.", progress = "With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!", completion = "At last!\n\nWith these bonds broken and the cudgel in my possession I shall send  the sea witch back to the icy depths...", sourceObjectiveStatus = "unverified-source-field" }
quests[10902] = { id = 10902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Elixirs", description = "I've devoted my life to perfecting my elixirs.  Despite my success, I haven't been able to create an elixir of eternal life.\n\nI think I know the reagent I'm missing.  I've heard of a place called the Caverns of Time in Azeroth where intruders known as rift lords and rift keepers phase in and out of the timeline.\n\nThis intrusive time-shifting creates tears in time itself, twisting it infinitely into crystallized essences.  Bring these to me along with samples of your work and I'll teach you all I know.", sourceObjective = "Go to the Black Morass in the Caverns of Time and obtain 10 Essences of Infinity from Rift Lords and Rift Keepers. Bring these along with  5 Elixirs of Major Defense, 5 Elixirs of Mastery and 5 Elixirs of Major Agility to Lorokeem in Shattrath's Lower City.\n\n*WARNING!* You can only select one alchemy specialization.", progress = "The essences!  Do you have them?", completion = "You are very good with elixirs, if these are any indication.  You will make a fine student.\n\nThese essences will provide me enough materials to formulate my recipe.  I will be known among all alchemists for this discovery!\n\nNow, if you're willing to learn, I am willing to teach.", sourceObjectiveStatus = "unverified-source-field" }
quests[10903] = { id = 10903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Honor Hold", description = "{name}, while you were on your mission in Zeth'Gor, I received news of my commanding officer, Colonel Jules.  He was stricken with a demonic corruption while fighting near the Gor'gaz Outpost, and his situation has grown very bad.\n\nYou have made such great gains for us against the fel orcs.  Your strength in battle is without question... is your spirit just as strong?\n\nPlease, return to Honor Hold and speak with Klatu, in an upper room at the Honor Hold inn.", sourceObjective = "Speak with Assistant Klatu, at Honor Hold's inn.", completion = "Yes, it is true.  Colonel Jules' situation has grown much worse these past days.  Anchorite Barada is busy praying for him... let us hope he may be cured.", sourceObjectiveStatus = "unverified-source-field" }
quests[10904] = { id = 10904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvesting the Fel Ammunition", description = "We must shut down the Burning Legion's access to Death's Door, but first you're going to destroy their two warp-gates!\n\nThe problem is, we can't even scratch one of those things, so you're going to need to use their own weapons against them.\n\nThe death's might, death's watch, deathforge over-smiths and deathforge technicians carry the ammunition for the fel cannons.\n\nNormally it wouldn't affect any of them, but if you bring the cannonballs to me, I will imbue them with Nature's unbridled wrath!", sourceObjective = "Collect 5 Fel Cannonballs.", progress = "Do you have the cannonballs yet?", completion = "Those things stink more than I thought they would!\n\nQuickly, hand them over to me and I will imbue them with Nature's force such that they will prove extremely deadly to their fel masters and their unnatural creations.", sourceObjectiveStatus = "unverified-source-field" }
quests[10905] = { id = 10905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Potions", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in potion creation, I would recommend that you seek the help of Lauranna Thar'well of the Cenarion Expedition.\n\nHer knowledge of plants will allow you to make the most of your raw materials.  Look for her in Zangarmarsh and tell her I sent you to her.", sourceObjective = "Speak to Lauranna Thar'well at Cenarion Refuge in Zangarmarsh.\n\n*WARNING!* You can only select one alchemy specialization.", completion = "You want me to help you with your study of potions?  Very well, {name}.  Let's see what we can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10906] = { id = 10906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Elixirs", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in elixir creation, I would recommend that you seek the help of the arakkoa known as Lorokeem.\n\nHis knowledge of elixirs is unmatched, yet he  squanders his skill pursuing an elixir of eternal life.  Find him and see what he can teach you.", sourceObjective = "Speak to Lorokeem in Shattrath's Lower City.\n\n*WARNING!* You can only select one alchemy specialization.", completion = "You want to learn from me?  Hmmm, yes.  Perhaps you'll be a suitable student.", sourceObjectiveStatus = "unverified-source-field" }
quests[10907] = { id = 10907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Transmutation", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in transmutation, I would recommend that you seek the help of the ethereal known as Zarevhi.  He resides in the Stormspire in Netherstorm.\n\nHis mastery of transmutation is... well, outlandish!  See what you can learn from him, but beware - ethereals drive a hard bargain.", sourceObjective = "Speak to Zarevhi at the Stormspire in Netherstorm.\n\n*WARNING!* You can only select one alchemy specialization.", completion = "You want me to help you with your study of transmutations?  Very well, {name}.  Let's see what we can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10908] = { id = 10908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Rilak the Redeemed", description = "You look surprised to be talking to me. I do not blame you. My people, the arakkoa, deserve to be feared.\n\nSpeak with Rilak the Redeemed in Shattrath City if you wish to know more. He can be found in the northern part of the Lower City, with the other outcasts of Skettis.\n\nAnd, {name}, we will speak again.", sourceObjective = "Kirrik the Awakened wants you to speak with Rilak the Redeemed in the Lower City section of Shattrath City.", completion = "So we meet, {name}. You must forgive the lack of formalities for time is of the essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[10909] = { id = 10909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Spirits", description = "Colonel Jules was cursed in a battle near the Gor'gaz Outpost, a haunt for Shattered Hand fel orcs.  My master, Barada, works feverishly to cure the poor human, but he needs help.  The Colonel's tormented spirit seeks peace, and his path to peace is, I fear, a path of vengeance.\n\nTake this anchorite relic to Gor'gaz Outpost.  Place it upon the ground near Shattered Hand orcs and defeat them.  This will release their fel spirits -- you must slay those fel spirits for Jules' own spirit's recovery.", sourceObjective = "Klatu in Honor Hold wants you to use the Anchorite Relic at Gor'gaz Outpost southwest of Honor Hold, slay Shattered Hand Berserkers near the relic, and then slay 10 released Fel Spirits to avenge Colonel Jules.", progress = "The fel spirits of the Shattered Hand orcs are a blight to poor Jules' soul.  Tell me, {name}... has he been appeased?", completion = "The Shattered Hand orcs are foul and beyond hope, but my heart is saddened that the road to salvation for Colonel Jules holds such bloodshed.", sourceObjectiveStatus = "unverified-source-field" }
quests[10910] = { id = 10910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death's Door", description = "Now there is an even greater threat from the Burning Legion.  To the south is a portal known as Death's Door, which opens upon the horrific world where the Legion breeds its deadly hounds.\n\nTo get there, exit Evergrove by heading east up the ramp.  Follow the path south, through the Bladed Gulch, Razaan's Landing, Razor Ridge and the Scalewing Shelf.  Then, take the ramp down into the Vekhaar Stand and enter Death's Door through the tunnel, south of Mok'Nathal.\n\nOnce there, use this druid signal.", sourceObjective = "Use the Druid Signal at Death's Door to call down and speak with an Evergrove Druid.\n\nProvided item:", completion = "It is a relief that Wildlord Antelarion has sent you to us.  The problem is much worse than first we feared!", sourceObjectiveStatus = "unverified-source-field" }
quests[10911] = { id = 10911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire At Will!", description = "Now that the ammunition can affect the Burning Legion, it's time for you to use it.\n\nThere are two warp-gates, which are used for teleportation and enhancement of the void terrors.  One is in the south and the other in the north, and each is within range of a fel cannon.\n\nUse the naturalized ammunition to take control of each fel cannon and destroy the warp-gates.\n\nAttack the gate with artillery to begin, and be prepared to kill its defenders to keep the cannon alive if necessary.", sourceObjective = "Use the Naturalized Ammunition to take control of the Death's Door Fel Cannons. Use the cannons to destroy both the South Warp-Gate and the North Warp-Gate.", progress = "Have you destroyed both of the warp-gates yet?", completion = "Your prowess is staggering!\n\nVery well, with the warp-gates out of the picture, there's only one thing left to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10912] = { id = 10912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hound-Master", description = "Baelmon the Hound-Master must die!  He maintains the ritual that keeps the portal functioning.\n\nThe Death's Door portal is located at the north end of the canyon.  When you find it, you will find Baelmon.\n\nYou're going to need help on this one, so take this wand.  When you battle the Hound-Master, use it and a couple of my friends will come to your aid.\n\nAfter you have defeated Baelmon, return to Wildlord Antelarion.\n\nAnd, {name}, thank you for all that you've gone through for us here.", sourceObjective = "Slay Baelmon the Hound-Master.", progress = "It is over then?  Has the danger at Death's Door been averted?", completion = "You are truly an amazing {race}!  If I thought that we were indebted to you before, then now there is simply no way in which we could ever repay you.\n\nBut we'll give it a try.  Thank you, hero of Evergrove!", sourceObjectiveStatus = "unverified-source-field" }
quests[10913] = { id = 10913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Improper Burial", description = "Is there nothing that can be done to stem the tide of corruption? My soldiers have been battling the Auchenai for days now with no end in sight. Each casualty, whether Auchenai or Sha'tar, is snatched from the battlefield - their souls lifted and taken to parts unknown.\n\nI will not have it! A proper burial is out of the question but those fiends will not have their souls! Take this torch and travel to the field of battle, directly east of here. Burn every corpse you see! We will not fuel their rituals.", sourceObjective = "Commander Ra'vaj at the Sha'tari Base Camp in the Bone Wastes of Terokkar Forest wants you to burn 8 Slain Auchenai Warriors and 8 Slain Sha'tar Vindicators.", progress = "It's a terrible thing to ask, I know...", completion = "<Commander Ra'vaj holds his head in his hands.>\n\nIt's not enough... It's just not enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[10914] = { id = 10914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero Is Needed", description = "It is not enough. A hero is needed. Our forces are overwhelmed as the Auchenai continue to grow in number.\n\n<Commander Ra'vaj looks at you.>\n\nWill you be the hero? Return to the field of battle and strike at their soldiers. Keep them occupied so that my scouts can get behind their lines and see what they are creating.", sourceObjective = "Commander Ra'vaj at the Sha'tari Base Camp in the Bone Wastes of Terokkar Forest wants you to slay 12 Auchenai Initiates and 5 Auchenai Doomsayers.", progress = "Take no prisoners!", completion = "You've done it, {name}! Because of you, we have made a new discovery...", sourceObjectiveStatus = "unverified-source-field" }
quests[10915] = { id = 10915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Exarch", description = "They are feeding the souls they steal to a coffin that they have dragged out from the Auchenai Crypts. My scouts believe the contents of the coffin to contain the first exarch of the crypts. They seek to resurrect the ancient one!\n\nYou must battle your way to the western side of Auchindoun and disturb the contents of that coffin before they feed it enough souls. Should you lose your way, follow the walking souls.\n\nDestroy whatever is inside that coffin!", sourceObjective = "Commander Ra'vaj at the Sha'tari Base Camp in the Bone Wastes of Terokkar Forest wants you to destroy the contents of the Auchenai Coffin.", progress = "You must destroy the ancient evil before it has regained its powers.", completion = "Victory is ours! This defeat will set the Auchenai back several weeks.", sourceObjectiveStatus = "unverified-source-field" }
quests[10916] = { id = 10916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging for Prayer Beads", description = "Anchorite Barada plans to exorcise the corruption from Colonel Jules, and will require an assistant for the task.  Such an assistant must be prepared...\n\nI am ashamed to admit that my prayer beads were lost in Honor Hold's courtyard.  I believe the dog Fei Fei stole them and buried them, but I do not know where.  If you speak with his master, Warrant Officer Tracy Proudwell, perhaps she will know where Fei Fei hides his stolen treasures.", sourceObjective = "Recover the Draenei Prayer Beads and bring them to Assistant Klatu in Honor Hold.", progress = "Have you found the prayer beads, {name}?  Their powers are crucial to many holy rites... including the rite of exorcism.", completion = "You found the prayer beads!  Well done, {name}.  You are a wonder, indeed -- you slay the horrors of Hellfire Peninsula one moment and find lost treasures the next.  Your people truly inspire!\n\nIt is good that you recovered these beads... for they will be invaluable in the exorcism ritual to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[10917] = { id = 10917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Outcast's Plight", description = "As an outcast, I am marked for death by arakkoa loyal to the city of Skettis.  I cannot leave these walls for fear of my life, but that doesn't mean I cannot strike at them in retaliation.\n\nI have a small cache of treasure that I'm willing to part with, should you help me strike back at my would-be assassins.  Bring me feathers from the denizens of the various Veils of Terokkar as proof of their demise.", sourceObjective = "Bring 30 Arakkoa Feathers to Vekax in Shattrath's Lower City.", progress = "Do you bring the feathers I asked for, {name}?", completion = "<Vekax squawks in glee as you present him with proof of his enemies' demise.>\n\nYes, that will show Skettis that we Outcasts will not take their punishment lying down.  Here is the reward I promised you.  I can arrange for more, should you provide me with additional feathers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10918] = { id = 10918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Feathers", progress = "Skettis's lapdogs still keeps a close watch over us, outcasts.  The moment any of us sets foot outside Shattrath we'll be as good as dead.\n\nBring me more feathers as proof of your victory over them.", completion = "<Vekax squawks in glee as you present him with proof of his enemies' demise.>\n\nYes, that will show Skettis that we Outcasts will not take their punishment lying down.  Here is the reward I promised you.  I can arrange for more, should you provide me with additional feathers.\n\n<This quest can be repeated up to Honored reputation.>" }
quests[10919] = { id = 10919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fei Fei's Treat", progress = "Fei Fei looks at you expectantly...", completion = "<Fei Fei barks happily and grabs the doggy treat.  He looks left and right... deciding where he should hide this new treasure...>" }
quests[10920] = { id = 10920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Fallen", description = "When the dreadfang widows attacked our outpost we heard the voice of the naaru calling us to battle.  We pursued the creatures into the night.  Some of our people we found dead in the dark, others we could hear struggling against their captors. \n\nBy morning we had come to this place and we fought a fierce battle but we were beaten.  Dreadfang poison will soon take my companions and I cannot last long.  Before I die I must know that the dreadfang widows were beaten.", sourceObjective = "Vindicator Haylen wants you to slay 20 Dreadfang Widows and then return to him just west of Netherweb Ridge.", progress = "I can feel the poison flowing through my veins.  The naaru call to me, I can see the light.  Are the dreadfang widows defeated?", completion = "I heard the sounds of your battle from here, {class}.  The sounds of your victory filled my heart with hope.  If you can win against such terrible odds, perhaps I can find the strength to drag my companions from this terrible place.", sourceObjectiveStatus = "unverified-source-field" }
quests[10921] = { id = 10921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokkarantula", description = "You have slain many of the dreadfang widows but they will continue to spawn and soon they will strike at us again.  Deep within Netherweb Ridge is the lair of the Terokkarantula, the brood-mother of these gruesome creatures.  If we are to be safe, she must die.", sourceObjective = "Vindicator Haylen wants you to kill the Terokkarantula and then return to him west of Netherweb Ridge.", progress = "Has Terokkarantula been slain?", completion = "The dreadfangs are beaten.  You have killed many and even their foul mother has fallen before you.  I am too poisoned to fight my way to freedom.  \n\nPlease, take some of my equipment.  It will lighten my load and give you the tools you need to make the journey back to Sha'tar Outpost.", sourceObjectiveStatus = "unverified-source-field" }
quests[10922] = { id = 10922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Through Bones", description = "Oy! You look like you can take care of yerself, {race}. Me and the crew here are looking for a bodyguard to watch over us while we hit a dig site to the north. The pay is pretty good and all you gotta do is make sure no nasty creatures kill me or any of my employees.\n\nIf you successfully make it back without any casualties, Dwarfowitz over there will pay ya.", sourceObjective = "Escort Letoll and his crew and protect them while they make their dig. Return to Dwarfowitz at the Sha'tari Base Camp if you succeed.", progress = "You get paid when the job is done, sonny.", completion = "A bone wurm! Fantastic! This may actually be the first time in recorded history that Letoll has actually made a discovery.", sourceObjectiveStatus = "unverified-source-field" }
quests[10923] = { id = 10923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evil Draws Near", description = "Now you must use the Dread Relic in a foul necromantic ritual if you wish to challenge Teribus the Cursed.  To the northeast, beyond Auchindoun, is the Writhing Mound, a place where necromancers gather.  \n\nThe auchenai death-speakers and doomsayers carry doom skulls that are laced with powerful necro-enchantments.  If you collect enough skulls you can use their power along with the power of the Dread Relic to command Teribus to face you.", sourceObjective = "Oakun wants you to take the Dread Relic to the Writhing Mound. Once there, kill Auchenai Death-Speakers and Auchenai Doomsayers to collect 20 Doom Skulls. Then find the Writhing Mound Summoning Circle and use the Dread Relic to summon and destroy Teribus the Cursed. Return to Oakun when the deed is done.", progress = "Has Teribus the Cursed been purged from the skies of Terokkar?", completion = "A great evil has been cleansed from Terokkar.  The Sha'tar are in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10924] = { id = 10924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Imp-ossible!", description = "The blood of the warp chasers in this area is a powerful and rare reagent. It's one of my biggest sellers.\n\nNormally, I take my imp, Zeppit, out to help me gather it. Warp chaser blood is simply too caustic to be handled safely by you or I, but it doesn't bother Zeppit.\n\nThings are getting busier here at the shop, so if I send Zeppit with you, will you help gather the blood? Zeppit's attention tends to wander, so you'll need to be close to the chaser when it dies for Zeppit to do his work.", sourceObjective = "Bring 8 vials of Warp Chaser Blood to Sab'aoth at Cosmowrench.", progress = "Did Zeppit cooperate enough for you to get all the blood I'll need?", completion = "This should prove a large enough supply for my needs.\n\nI hope the imp didn't give you too much trouble. He has a bit of a nasty mouth on him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10926] = { id = 10926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sha'tari Base Camp", description = "We will not make it back on our own.  The dreadfang poison is too strong. You must return to Sha'tari Base Camp for us.  Scout Navrin will send a rescue party out to find us.", sourceObjective = "Vindicator Haylen wants you to return to the Sha'tari Base Camp in the Bone Wastes and speak with Scout Navrin.", completion = "It is good to know that some of our warriors fought well against the dreadfang widows.  We will send a rescue party immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[10927] = { id = 10927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing the Crawlers", description = "Commander Skyshadow wants this tunnel cleared out so we can expedite trade with the Harborage. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Commander Skyshadow at once!", sourceObjective = "Slay 6 Cavern Crawlers.", completion = "Good work, {class}. That tunnel is our lifeline to the swamp.", sourceObjectiveStatus = "unverified-source-field" }
quests[10928] = { id = 10928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing the Crawlers", description = "Tor'chunk Twoclaws wants this tunnel cleared out so we can expedite trade with Swamp Rat. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Tor'chunk Twoclaws at once!", sourceObjective = "Slay 6 Cavern Crawlers.", completion = "Good work, {class}. That tunnel is our lifeline to the swamp.", sourceObjectiveStatus = "unverified-source-field" }
quests[10929] = { id = 10929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fumping", description = "How would you like to do a little more work for the Explorers' League? These bone worms have us all quite intrigued.\n\nI've got a drum right here that you can use out in the Bone Wastes. Just bang on the damned thing and see what you get. If it's a worm, kill it and bring back the carcass for us to study. We'll need a good lot of carcasses to get a valid testing sample.", sourceObjective = "Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to bring him 8 Mature Bone Sifter Carcasses.", progress = "We think the one that popped up at the dig was actually a baby worm!", completion = "Sand gnomes? Yea, sure... The desert can do strange things to a person.\n\nI think we're about to make a breakthrough here with these worms!", sourceObjectiveStatus = "unverified-source-field" }
quests[10930] = { id = 10930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Bone Worm", description = "I was right! These carcasses you brought me belong to maturing worms. Do you know what that means? It means that somewhere out there is a big one! I think we can get it to come out if we can provide the right kind of food. Let's see... something big! Yes!\n\nI remember seeing clefthooves east of here on the other side of the Bone Wastes. Get out there and kill a clefthoof. Once it's dead, use the drums. Hopefully the big one will come up to feed. If you manage to kill it, bring me its organs!", sourceObjective = "Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to recover Enormous Bone Worm Organs.\n\nHe wants his Fumper back too.", progress = "Take a friend with you!", completion = "Amazing! Look at this stuff! The thing-a-ma-whatever has some sort of dust inside its whatcha-ma-bobber. Bah! I won't bore you with all this scientific jargon. I did manage to pull a few teeth from the little ones to make these incredibly sharp knives. Want one?", sourceObjectiveStatus = "unverified-source-field" }
quests[10931] = { id = 10931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Exodar", description = "Your master Caedmos of the Exodar has requested to see you.  It concerns your training, but I don't really know anything beyond that.", sourceObjective = "Speak with Caedmos at the Exodar.Your master Caedmos of the Exodar has requested to see you. It concerns your training, but I don't really know anything beyond that.", sourceObjectiveStatus = "unverified-source-field" }
quests[10932] = { id = 10932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Exodar", description = "Your master Caedmos of the Exodar has requested to see you.  It concerns your training, but I don't really know anything beyond that.", sourceObjective = "Speak with Caedmos at the Exodar.Your master Caedmos of the Exodar has requested to see you. It concerns your training, but I don't really know anything beyond that.", sourceObjectiveStatus = "unverified-source-field" }
quests[10933] = { id = 10933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Silvermoon", description = "Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.", sourceObjective = "Speak with Aldrae in Silvermoon City.Your master Aldrae in Silvermoon City has requested to see you. It concerns your training, but I don't really know anything beyond that.", sourceObjectiveStatus = "unverified-source-field" }
quests[10934] = { id = 10934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Silvermoon", description = "Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.", sourceObjective = "Speak with Aldrae in Silvermoon City.Your master Aldrae in Silvermoon City has requested to see you. It concerns your training, but I don't really know anything beyond that.", sourceObjectiveStatus = "unverified-source-field" }
quests[10935] = { id = 10935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exorcism of Colonel Jules", description = "{name}, it is time to save Colonel Jules.  His condition has worsened and Barada fears that, if we do not cleanse him of his corruption,  he will be lost to us.\n\nTake the prayer beads you found and speak with Anchorite Barada to begin the ritual.  Let no disruptions stop the ritual... and if all goes well, Colonel Jules will be saved.  Speak with Jules when he is saved, then return to me.", sourceObjective = "Speak with Anchorite Barada. Use the prayer beads to help with the ritual, and then speak with Colonel Jules when he is saved. Finally, return to Assistant Klatu.", progress = "Go to Anchorite Barada, {name}.  He must succeed with his ritual if the colonel is to be saved.", completion = "You have done it, {name}.  You have saved Colonel Jules' soul and cast the darkness within him back to where it came.  A great, noble deed this is!  A hero's day!", sourceObjectiveStatus = "unverified-source-field" }
quests[10936] = { id = 10936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollbane is Looking for You", description = "While we were busy, a messenger was waiting out in the hall.  I suppose he grew tired, or perhaps he simply ran away at the sight of Jules floating around the room.\n\nEither way, Force Commander Danath is looking for you.  I suggest that you seek an audience with him inside the barracks as quickly as possible!", sourceObjective = "Assistant Klatu has informed you that Force Commander Danath Trollbane has been seeking you. Speak to him in the barracks at Honor Hold in Hellfire Peninsula.", completion = "It's about time!  I heard all about what you've been up to with that draenei priest. You totally freaked my messenger out!\n\nNow that you're done with that, I have a little mission planned for you to Hellfire Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10937] = { id = 10937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drill the Drillmaster", description = "I'm receiving reports that the Shattered Hand fel orcs, out in front of Hellfire Citadel, are organizing for what looks like an all-out assault.  No doubt, they're not happy about your successes against all of the clans.\n\nGet to the base of the citadel, where the Path of Glory ends.  You'll find the fel orcs busy with their preparations, but you're going to catch them with their pants down.\n\nEliminate the one that's in charge of that force.  Kill Drillmaster Zurok!", sourceObjective = "Force Commander Danath Trollbane has ordered you to kill Drillmaster Zurok with all due haste. Return to the force commander at Honor Hold in the Hellfire Peninsula once the drillmaster is dead.", progress = "Is the drillmaster dead?  Hmm, maybe my scouts are wrong?", completion = "I wasn't going to believe it until I heard it from you, personally.  Already our scouts are trickling in with information that the Shattered Hand are in disarray without their precious drillmaster to tell them what to do.\n\nYou've traveled a long road, {name}.  I trust that you will accept this armor along with my thanks.  Wear it proudly, you've earned it!", sourceObjectiveStatus = "unverified-source-field" }
quests[10938] = { id = 10938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Blessings Deck", description = "Now that you have gathered all of the Blessings cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Blessings Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Blessings!   Congratulations!", completion = "So you have put together a deck of Blessings.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10939] = { id = 10939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Storms Deck", description = "Now that you have gathered all of the Storms cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Storms Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Storms!   Congratulations!", completion = "So you have put together a deck of Storms.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10940] = { id = 10940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Furies Deck", description = "Now that you have gathered all of the Furies cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Furies Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Furies!   Congratulations!", completion = "So you have put together a deck of Furies.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10941] = { id = 10941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Lunacy Deck", description = "Now that you have gathered all of the Lunacy cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Lunacy Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Lunacy!   Congratulations!", completion = "So you have put together a deck of Lunacy.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10942] = { id = 10942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children's Week", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", sourceObjective = "Use the Blood Elf Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item:", completion = "Hmph, you're my sponsor?  I'm Salandria!  I've been here ever since I was a little baby.  My parents were taken by the war, so I have to live here at the orphanage.\n\nIt's not that bad, but I always wanted to go places -- I haven't ever stepped foot outside of the city.  I've already made a list of all the cool places that I want to go, and the awesome things that I want to do.\n\nI'm ready to go when you are!", sourceObjectiveStatus = "unverified-source-field" }
quests[10943] = { id = 10943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children's Week", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", sourceObjective = "Use the Draenei Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item:", completion = "You must be the adventurer who's going to be my big brother for Children's Week!  I'm Dornaa, pleased to meet you.\n\n<She looks sad for a moment.>\n\nMother and father were killed in the war, and I've lived in the orphanage all my life.  It's nice, actually, but I've always wanted to go places and see things.\n\nI've already made a list of places we could visit, if that's okay?  I just know that we're going to have a great time together!\n\nI'm ready to go when you are!", sourceObjectiveStatus = "unverified-source-field" }
quests[10944] = { id = 10944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret Compromised", description = "Thanks again, {name}.  I recognize your name.  Akama has entrusted you with his plans and so I will trust you as well.\n\nThe naga discovered I was working against Illidan and tried to get me to speak by torturing me.  I did not tell them a thing - Akama himself taught me to master pain through meditation.\n\nIllidan asked the naga to bring me to him.  He would have seen right through my flesh and into my soul's deepest secrets.\n\nAkama must be warned.  Our plans are in jeopardy!", sourceObjective = "Travel to the Warden's Cage in Shadowmoon Valley and speak to Akama.", completion = "I thank you, {name}.  Olum is one of my dearest friends and most trusted followers.  His contributions have been of vital importance to our plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[10945] = { id = 10945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hch'uu and the Mushroom People", description = "I had a friend named Hch'uu.  She told me that she ended up in the orphanage because she had to run away from an evil fungal giant and got lost.\n\nWe had great fun until her people came and took her away last year.  I think she said she was going to live at a place called Sporeggar.\n\nI'd like to go to see her and have a look at her mushroom village.  The orphan matron told me that it is on the west side of Zangarmarsh, between the Sporewind and Marshlight lakes.\n\nCan we go?  Can we go?  Please?!", sourceObjective = "Take your orphan, Salandria, to Sporeggar in Zangarmarsh. Make sure to call for her if she is not present when you arrive. Then, speak with Hch'uu.", progress = "You're the adventurer that brought her here?", completion = "Thank you for this chance to once again see Salandria.  I have missed her so much this past year, but we are still good friends.\n\nWe agreed that when we grow up, we're both going to be brave adventurers, just like you!", sourceObjectiveStatus = "unverified-source-field" }
quests[10946] = { id = 10946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruse of the Ashtongue", description = "Olum's sacrifice was tremendous.  I would never have asked him to give up his life myself.  But it is done.\n\nIf we're to lure Illidan back into a false sense of security, we need to do his bidding - at least for now.\n\nI command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted.\n\nYou are to perform the deed that Illidan demands.  Take this cowl; it is magical in nature.  You will appear to be one of my men to any who see you slaying Kael's phoenix, Al'ar.", sourceObjective = "Travel into Tempest Keep and slay Al'ar while wearing the Ashtongue Cowl. Return to Akama in Shadowmoon Valley once you've completed this task.", progress = "Is the deed done, {name}?  Illidan is not a patient master!", completion = "You've done well, {name}.  This will bring us a step closer to shifting Illidan's focus away from us and from...\n\n\n\nMore work remains to be done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10947] = { id = 10947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Artifact From the Past", description = "Illidan's attention is now on Kael'thas, thanks to you.  The time has come to make our move.\n\nI've had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill.  Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal.\n\nThere might be a way to retrieve this artifact, however.  Legend speaks of a place in Azeroth guarded by bronze dragons...  a place where past and present meet.  It is there you will find what we seek.", sourceObjective = "Go to the Caverns of Time in Tanaris and gain access to the Battle of Mount Hyjal. Once inside, defeat Rage Winterchill and bring the Time-Phased Phylactery to Akama in Shadowmoon Valley.", progress = "Have you retrieved the phylactery yet, {name}?", completion = "My vision... it all becomes clear now.  The powers this artifact has over a soul.... to contain it... to siphon it into itself... I will use those powers to reclaim what belongs to me!  The time has arrived for us to take the fight to Illidan!", sourceObjectiveStatus = "unverified-source-field" }
quests[10948] = { id = 10948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hostage Soul", description = "You might wonder why I go to such lengths to hide my intentions.  Why not throw my lot in openly with the naaru?\n\nMy very essence - my soul - is held prisoner inside the Black Temple.  Illidan could destroy me any moment... until now!  This phylactery will allow me to regain control of my soul.\n\nThe time has come, {name}.  I'll lead Maiev and my Deathsworn to Illidan's doorstep.\n\nSpeak to A'dal and and tell him of our plan.  If we strike together we'll break through Illidan's defenses.", sourceObjective = "Travel to Shattrath City to tell A'dal about Akama's request.", completion = "<A'dal's light surrounds you as he welcomes you back.  You have a feeling he knows what you're about to ask of him.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10949] = { id = 10949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entry Into the Black Temple", description = "<A'dal shows you an image of a naaru outside of the Black Temple, fighting alongside draenei vindicators and blood elf magisters.  You immediately understand that this is the distraction Akama is waiting for.>", sourceObjective = "Travel to the entrance to the Black Temple in Shadowmoon Valley and speak to Xi'ri.", completion = "<Xi'ri appears to acknowledge your presence.  He seems to be focused on the battle in the surrounding area.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10950] = { id = 10950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun and the Ring of Observance", description = "One of the priests that comes to visit told a story about a place nearby.  It's called Auchindoun, and it's supposed to be very important to the draenei.\n\nHe said it used to be the place where the bodies of the draenei were taken when they died.  But some time ago, something bad blew it up.\n\nI'd like to see its Ring of Observance.  The orphan matron told me that it is in the middle of the Bone Wastes, on the south side of the Terokkar Forest.\n\nPlease, <Mr./Miss> {name}, can we go?", sourceObjective = "Take your orphan, Dornaa, to the Meeting Stone at the Ring of Observance in the middle of Auchindoun. Auchindoun, in turn, is in the middle of Terokkar Forest's Bone Wastes. Make sure to call for her if she is not present when you arrive.", progress = "Are we there yet?  Just protect me from all the spooky ghosts, okay?", completion = "Oh, it's just wonderful!  I mean, it looks pretty old... and yeah, someone sure did blow it up.  But just look at it!\n\nOoh, and did you look up at the sky?\n\nNeato!", sourceObjectiveStatus = "unverified-source-field" }
quests[10951] = { id = 10951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trip to the Dark Portal", description = "How can we look at all of these interesting places and not see the Dark Portal?!\n\nThe grown-ups are always trying to tell us scary stories about it and how it's so dangerous, with lots of demons, and stuff.\n\n<Salandria rolls her eyes.>\n\nBut you're here, so it can't be too bad, right?\n\nI want to see for myself.  You remember where it is on the east edge of Hellfire Peninsula?", sourceObjective = "Take your orphan, Salandria, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive.", progress = "This is soooo exciting!", completion = "The stories don't even come close to how cool this place is.  It's amazing!\n\nIs it true that a powerful wizard named Medivh created it?\n\nI wonder what's on the other side?  You've been there, right?  Hmm, we should definitely go someplace on the other side of the Dark Portal!", sourceObjectiveStatus = "unverified-source-field" }
quests[10952] = { id = 10952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trip to the Dark Portal", description = "There's one place that if we don't go anywhere else, we have to go to: the Dark Portal!\n\nThe orphan matrons are always trying to scare us with stories about how dangerous it is, with lots of demons, and people like you coming through it.\n\n<Dornaa rolls her eyes.>\n\nBut you're here, and nice, so it can't be too bad, right?\n\nI want to see it for myself.  You remember where it is on the eastern edge of Hellfire Peninsula?", sourceObjective = "Take your orphan, Dornaa, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive.", progress = "What do you know about the Dark Portal?", completion = "The orphan matron's stories don't even come close to how cool this place is.  It's amazing!  She said that it was created by a powerful wizard named Medivh.\n\nWhat's on the other side of it?  You've been there, right?  We should most definitely go someplace on the other side of the Dark Portal!", sourceObjectiveStatus = "unverified-source-field" }
quests[10953] = { id = 10953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visit the Throne of the Elements", description = "Have you heard of the Throne of the Elements?  It's supposed to be this place in Nagrand where there are these powerful elementals.\n\nOne day soon, I'm going to be a powerful mage, or maybe a warlock.  I'm gonna have to learn about some of the elemental forces!\n\nDo you think maybe that we could go there?\n\n<Salandria looks at you slyly.>\n\nYa know, it would be educational to go there.  It's supposedly just north of Garadar, on the other side of Skysong Lake.", sourceObjective = "Take your orphan, Salandria, to the Throne of the Elements in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Elementalist Sharvak.", completion = "You bring a child here?  Foolhardy, but I promise that she will come to no harm, at least as long as she doesn't get too close to Incineratus.\n\nHmm, unfortunate that she's a blood elf.  Were she capable of a deep connection to the world, we could teach her some things so that she might aid us to heal its wounds.  But, perhaps her exposure to the elements here will give her some insight into their workings.\n\nGo in peace and see to it that you take good care of her.", sourceObjectiveStatus = "unverified-source-field" }
quests[10954] = { id = 10954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jheel is at Aeris Landing!", description = "I miss my brother, Jheel.  He's a couple of years older than me, so they let him start an apprenticeship with the ethereal in Nagrand.\n\nIt sure would be nice to go visit him.  He loves geology and stuff, so I bet he's having a great time.\n\nThe orphan matron told me that he's training at a place called Aeris Landing in Nagrand.  It's supposed to be along the road, far to the west of Telaar, and northwest of the great mountain, Oshu'gun.", sourceObjective = "Take your orphan, Dornaa, to Aeris Landing in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Jheel.", progress = "Did you bring her here?", completion = "Oh, I've missed Dornaa so much.  Thank you for bringing her to visit.  It gets lonely here with only the ethereal around.  And they're so serious all the time with this Oshu'gun business.\n\nBut I get to go back and visit the orphanage after I pass my gemcutting exams.  I almost passed them last week, but I'm sure that I'll do better on the test tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[10955] = { id = 10955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morthis Whisperwing", description = "Before all of the druidic orders coalesced into the Cenarion Circle, the Druids of the Talon were responsible for teaching promising young druids the mysteries of flight. With the dissolution of the order, former members teach the skill sparingly.\n\nEven now, Morthis Whisperwing continues his search for a suitable apprentice. Few druids have truly mastered all the forms available to them, but you show the promise Morthis requires of his students. Seek him out at the Cenarion Refuge in Zangarmarsh.", sourceObjective = "Seek out Morthis Whisperwing at the Cenarion Refuge in Zangarmarsh.", completion = "<Morthis considers you somewhat skeptically.>\n\nI have long searched for an apprentice to pass my knowledge to. Though the Druids of the Talon are no longer a formal group, I shall remain one to the last of my days.\n\nI accept you as my apprentice from this moment forward. For my part, I will teach you the secrets of the stormcrow. For your part, you must be prepared to do all I ask. Do you understand?", sourceObjectiveStatus = "unverified-source-field" }
quests[10956] = { id = 10956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seat of the Naaru", description = "Do you know anything about the naaru?  They're these angelic beings that have been helping the draenei for a really long time.  I've seen a bunch around Shattrath.\n\nThey say that one naaru, O'ros, was with the Exodar when it traveled to your homeworld.  I should like to see for myself.\n\nCan you take me there?  I bet we could get there fast by using one of the portals inside the Temple of the Moon in Darnassus!  When we get there, if you get lost, we could always just look at your map.", sourceObjective = "Take your orphan, Dornaa, to stand before O'ros at the bottom of the Seat of the Naaru inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive.\n\nRemember that you can use your map inside the city.", progress = "I have been expecting you.", completion = "<You feel, more than hear, the musical voice of O'ros chiming in your mind.>\n\nThank you for bringing this child to me, {name}.  She is very special indeed, and will grow up one day to be an important figure amongst the draenei.  This is in no small part due to the kindness that you have shown her, and the impression that you have made.", sourceObjectiveStatus = "unverified-source-field" }
quests[10957] = { id = 10957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption of the Ashtongue", description = "When Illidan obtained the Broken's allegiance, Akama was our wisest.  He knew that openly opposing the Betrayer would lead to the extinction of our race.\n\nInstead he has plotted and schemed for this very moment under utmost secrecy.  Failure would be catastrophic... not just for Akama, not just for the Broken, but for all of Outland.  No one this close to Illidan has ever been able to deliver such a terrible blow to him.\n\nHelp Akama free his soul and he will grant you access to Illidan's sanctum.", sourceObjective = "Help Akama wrest control back of his soul by defeating the Shade of Akama inside the Black Temple. Return to Seer Kanai when you've completed this task.", progress = "Yes, {name}?", completion = "It is done, {name}.  The time to strike at Illidan has come.", sourceObjectiveStatus = "unverified-source-field" }
quests[10958] = { id = 10958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out the Ashtongue", description = "<As you look up at Xi'ri, your mind becomes focused and your will determined.  Your work here is not done; you must go inside the Black Temple and find Akama's followers.>\n\n<Much depends on Akama's success.>", sourceObjective = "Find Akama's Deathsworn inside the Black Temple.", completion = "We've been expecting you, {name}.  Akama is in great need of your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[10959] = { id = 10959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of the Betrayer", description = "With Illidan's lieutenants defeated, Akama will be able to force open the doors to Illidan's sanctum.  Be ready to bring your force inside as soon as Akama does.\n\nWe still do not know what has become of Maiev, but we must make our move without her.\n\nI hope your force is up to the task.  Illidan will not be pleased to see Akama.", sourceObjective = "Seer Kanai wants you to defeat Illidan inside the Black Temple.", progress = "Yes, {name}?", completion = "It is as it was foretold, {name}.  One by one, Illidan's lieutenants have fallen... and now the Betrayer himself has met his demise!\n\nKnow this, {name}: every decision Akama made and every moment of his life since Illidan arrived, Akama planned for this moment.  Illidan is finally dead and our people... are free!", sourceObjectiveStatus = "unverified-source-field" }
quests[10960] = { id = 10960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When I Grow Up...", description = "When you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock, like I said before?  Or maybe a paladin Blood Knight?  Yeah, definitely a Blood Knight!\n\nThey say that the true ones are trained in Silvermoon City on your world.  Could you take me there?  The stories that I've heard say that the paladin trainers reside in the Farstriders' Square in that city.\n\nPlease take me there.  Please!", sourceObjective = "Take your orphan, Salandria, to the paladin trainers in Silvermoon City's Farstriders' Square. Make sure to call for her if she is not present when you arrive. Then, speak with Lady Liadrin, the Blood Knight Matriarch.\n\nRemember that you can use your map inside the city, and speak to the guards to find the paladin trainers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10961] = { id = 10961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ward of Wakening", description = "Long ago, the relics used to teach the ways of the stormcrow were entrusted to an ancient druid.\n\nYour training requires these relics, so we must wake their guardian from his slumber.\n\nI will prepare a potion you can use to ease the process. The mixture requires common herbs, as well as bogblossom, which usually grows atop the tallest mushrooms in the marsh. Fly up there and pursue them but take care, as they're quite fragile and may explode violently if mishandled.", sourceObjective = "Bring 10 Bogblossoms, 10 Ancient Lichen, and 10 Dreaming Glory to Morthis Whisperwing at the Cenarion Refuge.", progress = "Have you brought the ingredients for the draught? Take care not to get pollen on me, please. I sneeze uncontrollably in its presence.\n\n<Morthis sniffs at the indignity represented by a sneeze.>", completion = "<Morthis accepts the herbs from you, inspecting them. Producing a vial, he begins mixing the potion.>\n\nThis will only take a moment, {name}. Then, you must travel to Moonglade.", sourceObjectiveStatus = "unverified-source-field" }
quests[10962] = { id = 10962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Visit the Caverns", description = "In the orphanage, the old priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nDo you think that we could go there?  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nMaybe you could buy me a souvenir while we're there?", sourceObjective = "Take your orphan, Dornaa, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive.\n\nThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel.", progress = "You think it's true what they say about the Caverns of Time?", completion = "Neato!  A dragon of my very own!  One day I hope that I'm lucky enough to have a dragon as a friend.\n\n<Dornaa bounces up and down with joy, fiercely hugging her new toy.>\n\nThis has been the best trip ever!  I hope it never ends.", sourceObjectiveStatus = "unverified-source-field" }
quests[10963] = { id = 10963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Visit the Caverns", description = "In the orphanage, the old stinky priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nI think we should go there.  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nYou could buy me a souvenir while we're there!", sourceObjective = "Take your orphan, Salandria, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive.\n\nThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel.", progress = "If what they say about the Caverns of Time is true, then it must be a place of great power.", completion = "Awesome!  A dragon of my very own!  Someday I plan to own a real one.\n\n<Salandria slyly eyes her new toy, the gears within her mind turning.>\n\nThis has been the best trip ever!  I hope it never ends.", sourceObjectiveStatus = "unverified-source-field" }
quests[10964] = { id = 10964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking the Sleeper", description = "Take the ward with you and travel to Moonglade, to the Stormrage Barrow Dens. Within the southernmost of the Stormrage Barrow Dens, watched over by the dreamwardens, you will find Clintar Dreamwalker.\n\nAdminister the potion and watch over him while he wakes. He'll be extremely vulnerable as his spirit reunites with his body and he certainly won't recognize you. Declare yourself to him as soon as he comes around, {name}. He will need your help to gather the relics for the ceremony.", sourceObjective = "Use the Ward of Waking to help Clintar Dreamwalker emerge from the Emerald Dream. When he is conscious, speak to him.", progress = "<You prepare to administer the potion to the sleeping {class}.>", completion = "<The {class} emerges from his sleep, groggy and haggard looking. His gaze darts around the room in search of unseen pursuers.>\n\nMorthis?\n\nNo, you're not Morthis... Who are you, {race}, and why have you disturbed my rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[10965] = { id = 10965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mere Dream", description = "<Clintar listens as you relay Morthis' instructions, nodding, but clearly fearful.>\n\nI cannot extricate myself fully from the Emerald Dream to help you, but a fragment of my spirit will guide you in your search for the relics. Guard it well, {race}, for it is a fragile thing.\n\nThe Emerald Dream itself has become an alien, dangerous place. Its grasp on me is strong, and I will not be whole until the Emerald Dream returns to normalcy. What you see around you is but an echo of the reality inside the dream!", sourceObjective = "Protect Clintar Dreamwalker's Spirit while it gathers the relics of Aviana, then speak to Dreamwarden Lurosa.", progress = "Be quick, {race}. If these creatures escape the barrow, Clintar Dreamwalker will not be the only one in danger.", completion = "You are fortunate that Clintar was strong enough to maintain the split in his essence for so long, {name}. Few druids can manage that kind of feat while under attack in Emerald Dream. Guard the relics well!", sourceObjectiveStatus = "unverified-source-field" }
quests[10966] = { id = 10966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Orphanage", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, {name}!  You're my big <brother/sister> now!\n\n<Dornaa's eyes begin to well up with tears.>\n\nI'm going to miss you so much!  When I grow up, I'm going to be just like you!!!", sourceObjective = "Return your ward to the Shattrath City orphanage by handing in the Draenei Orphan Whistle to Orphan Matron Mercy in the Lower City.", progress = "It is good to see you again, {class}.  I trust that you and young Dornaa had a wonderful time together?", completion = "It is good for the soul to know that there are heroes such as yourself that are willing to give of their time so selflessly.\n\nI can tell already that your time together with Dornaa has made a huge impression.  It's good for the children to have a chance to get out and see the world.\n\nHere, she told me that she wanted you to take care of one of her favorite pets, just like you took care of her.  Something to remember her by.\n\nDon't be a stranger.", sourceObjectiveStatus = "unverified-source-field" }
quests[10967] = { id = 10967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Orphanage", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, {name}!  You're my big <brother/sister> now!\n\n<Salandria's eyes begin to well up with tears.>\n\nI'm going to miss you so much!!!", sourceObjective = "Return your ward to the Shattrath City orphanage by handing in the Blood Elf Orphan Whistle to Orphan Matron Mercy in the Lower City.", progress = "It is good to see you again, {class}.  I trust that you and young Salandria had a wonderful time together?", completion = "It is good for the soul to know that there are heroes such as yourself that are willing to give of their time so selflessly.\n\nI can tell already that your time together with Salandria has made a huge impression.  It's good for the children to have a chance to get out and see the world.\n\nHere, she told me that she wanted you to take care of one of her favorite pets, just like you took care of her.  Something to remember her by.\n\nDon't be a stranger.", sourceObjectiveStatus = "unverified-source-field" }
quests[10968] = { id = 10968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call on the Farseer", description = "I am sensing something very special about this child indeed.\n\nYou should take her to visit Farseer Nobundo, here in the Exodar.  I believe that he has been expecting the two of you.\n\nLook for Nobundo upon the highest terrace in the Crystal Hall.", sourceObjective = "Take your orphan, Dornaa, to visit Farseer Nobundo at the Crystal Hall inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive.\n\nRemember that you can use your map inside the city.", progress = "Remarkable.", completion = "I had hoped, but despaired she was only a figment of my imagination.  The child is amazing!\n\nIt's unheard of in this day and age that one of the draenei should exhibit such ability with the elements without any training.  She must have inherited this power from an ancient ancestor.\n\nI will send a missive to the orphan matron in Shattrath City requesting that the child be allowed to come stay with us.\n\nPlease, keep her safe until then.", sourceObjectiveStatus = "unverified-source-field" }
quests[10969] = { id = 10969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Ameer", description = "It would seem that an outside force has taken an interest in the business practices of the Consortium. Five Consortium dealers have gone missing in the past two days. We have reason to believe the Ethereum are involved. If you are interested in assisting, seek out Commander Ameer at the Protectorate Watch Post.\n\nYou will find the Protectorate Watch Post directly east of here on the next island.", sourceObjective = "Seek out Commander Ameer at the Protectorate Watch Post.", completion = "Aye, it is true, but the Consortium are not the only group claiming losses.", sourceObjectiveStatus = "unverified-source-field" }
quests[10970] = { id = 10970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mission of Mercy", description = "We salvaged this prison orb on our last scouting mission into Ethereum territory. We'd have never found it had it not been for the distress signal that it was faintly emitting.\n\nWe think one of our own might be locked up in there but we have no way of opening the orb up without harming whatever is inside.\n\nWhat we know about the Ethereum is that any of their members could - at any given time - be carrying a key to unlock an orb. Retrieve one and return so that we may uncover the mysteries of this orb.", sourceObjective = "Recover the Salvaged Ethereum Prison Key for Commander Ameer at the Protectorate Watch Post in Netherstorm.", progress = "Any luck?", completion = "Stand back, {name}. This could very well be an Ethereum trap.", sourceObjectiveStatus = "unverified-source-field" }
quests[10971] = { id = 10971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethereum Secrets", description = "<Ameer holds up a tag.>\n\nI found this prisoner I.D. tag with the remains of the fallen vanguard. I can only assume that all of their prisoners are tagged in the same manner.\n\nI'm going to start cataloguing the tags in hopes of making sense of their penal system. If in your adventures you find more Ethereum prison keys, you can use them to open the Ethereum prisons at the Ethereum Staging Grounds - directly south of here. Bring me back any and all I.D. tags that you find.", sourceObjective = "Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him an Ethereum Prisoner I.D. Tag.", progress = "Have you recovered any I.D tags?", completion = "It seems to be more than just an identifier. There is some sort of code written on these tags. I'm on the verge of breaking it wide open. Perhaps if I had a few more pieces.", sourceObjectiveStatus = "unverified-source-field" }
quests[10972] = { id = 10972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethereum Prisoner I.D. Catalogue", description = "I am in need of more I.D tags, {name}. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", progress = "I am in need of more I.D. tags, {name}. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", completion = "We are close to the truth, {name}." }
quests[10973] = { id = 10973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thousand Worlds", description = "I have cracked the code! Each tag is broken up into several segments. The front side of the tag is always the same and states: \"A Thousand Worlds...\" I am unsure as to the meaning of this phrase but it sounds insidious.\n\nOn the back side of the tag are the vital statistics. The first set of runes indicates location and the second indicates prisoner type. Furthermore, it would seem that the keys can be combined to form a special key that accesses another prison type. Now I just need more keys...", sourceObjective = "Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him 5 Ethereum Prison Keys.", progress = "I know it's asking a lot but think of the lives that could be saved!", completion = "<Ameer deftly combines the keys and begins to read the markings on the newly formed key tablet.>\n\n\"A thousand worlds shattered, a thousand worlds more to overcome... Such is the will of the Nexus-King.\"\n\n<Ameer turns the tablet over and begins to read from the back-side.>\n\nStasis chambers of Bash'ir?", sourceObjectiveStatus = "unverified-source-field" }
quests[10974] = { id = 10974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stasis Chambers of Bash'ir", description = "The Ethereum have a settlement on the northernmost shelf of Blade's Edge Mountains known as Bash'ir's Landing. According to the key tablet, much larger versions of the prisons are kept at Bash'ir's. It should also be noted that the Ethereum refer to those prisons as stasis chambers.\n\nThe key tablet grants access to a very specific stasis chamber at the landing known as Stasis Chamber Alpha. Take the key and investigate.\n\nMy image will be awaiting your return at Bash'ir's Landing. Speak to me there.", sourceObjective = "Use the Ethereum Key Tablet - Alpha to open Stasis Chamber Alpha at Bash'ir's Landing in Blade's Edge Mountains.\n\nReturn Evidence from Alpha to the Image of Commander Ameer at Bash'ir's Landing.", progress = "You made it! Any luck?", completion = "<The image of Commander Ameer rummages through the evidence.>\n\nIt is worse than I thought... These chambers hold ferocious beasts and creatures from many, many different worlds. They hope to one day command the beasts to do their bidding. We must destroy them all!", sourceObjectiveStatus = "unverified-source-field" }
quests[10975] = { id = 10975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purging the Chambers of Bash'ir", progress = "We're at an impasse here, {name}. The data you've collected has given us enough information to save our allies being held at the smaller prisons of Netherstorm but we must press forward and eradicate the larger Ethereum threats here at Bash'ir's Landing.\n\nJoin the battle against the Ethereum! Bring Ethereum prison keys to me and I shall forge Ethereum stasis chamber keys for you to use on the stasis chambers of Bash'ir.", completion = "There is always more work that must be done, {name}. Now seek out a stasis chamber and destroy whatever evil lurks within!" }
quests[10976] = { id = 10976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of the Nexus-King", description = "What I must now know is what the Ethereum have held inside the Mana-Tombs of Auchindoun.\n\nIn your battles against the beasts of the stasis chambers of Bash'ir you may run across an item known as the Mark of the Nexus-King. Should you find such an item, return it to me immediately! It is the final piece in crafting a key that will allow access to the stasis chamber inside the Mana-Tombs.", sourceObjective = "The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to bring him a Mark of the Nexus-King.", progress = "This will be your most daunting task, {name}.", completion = "At last!\n\n<Commander Ameer reads from the Mark of the Nexus-King.>\n\nTwo final prisons? I shudder to think what horrors lie in wait...", sourceObjectiveStatus = "unverified-source-field" }
quests[10977] = { id = 10977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stasis Chambers of the Mana-Tombs", description = "The Mark of the Nexus-King that you recovered has allowed me to forge a new key for the stasis chambers found inside the Mana-Tombs.\n\nAccording to the glyphs on the mark, two exist: one near the front and one near Nexus-Prince Shaffar. This key that I am about to give you will open the stasis chamber near the front.\n\nI want you to go to the Mana-Tombs of Auchindoun and open the Mana-Tombs Stasis Chamber.", sourceObjective = "The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to use the Mana-Tombs Stasis Chamber Key on the Stasis Chamber inside the Mana-Tombs of Auchindoun.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I would understand if you chose not to continue, {name}.", completion = "Word has gotten back of your heroics, {name}. Haramad and I both agree that what you've done deserves a great reward.\n\nThough... Nevermind, you've done enough. I cannot in good conscience ask anything more from you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10978] = { id = 10978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Morthis Whisperwing", description = "Now that the relics have been recovered, you must leave this place with all haste. Clintar risked his safety and that of the dreamwardens to help you, {name}, but now he must fully devote his attention to fighting the force that has invaded the Emerald Dream.\n\nTake the relics back to Morthis Whisperwing, along with word of what you've seen here. He may be able to help us identify just what Clintar is struggling against.", sourceObjective = "Bring the Relics of Aviana to Morthis Whisperwing at Cenarion Refuge in Zangarmarsh.", progress = "Did Clintar help you recover the relics?", completion = "<Morthis accepts the relics from you as you describe your experiences in the barrow dens.>\n\nThis is most troubling news, {name}. There have been any number of strange disturbances in the Emerald Dream, but I can't remember any mention of outside forces tampering with it. Are you certain that's what Clintar believes?", sourceObjectiveStatus = "unverified-source-field" }
quests[10979] = { id = 10979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Evergrove", description = "Are you certain you saw a raven in the barrow den?\n\nThis is a troubling development. There's little we can do to help Clintar and the dreamwardens directly, but if we can learn more about what's threatening the Emerald Dream, we may be able to stop it.\n\nWe've been learning about the resurgence in an ancient arakkoa cult in Blade's Edge -- one that venerates a raven god. Go to the Evergrove and find Arthorn Windsong. There may be a connection between what's happening there and in the Emerald Dream!", sourceObjective = "Speak with Arthorn Windsong at the Evergrove in Blade's Edge Mountains.", completion = "<Arthorn listens as you explain that Morthis Whisperwing sent you to investigate a connection between the cult of the raven god and strange happenings in Moonglade. Though shocked at the news, she seems more disappointed at the message's nature.>\n\nOh my...\n\nI've been helping Timeon with his research on the raven cult, but we never imagined its patron had any reach beyond Blade's Edge!", sourceObjectiveStatus = "unverified-source-field" }
quests[10980] = { id = 10980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of the Raven", description = "From what you've told me, Morthis's suspicions seem plausible, but we need confirmation.\n\nIn his research, Timeon has uncovered clues that a \"book of the raven\" served as an ancient scripture to the cult.\n\nThe arakkoa spirits will not reveal themselves to your eyes. Take this stone with you to the high peaks in the western part of Blade's Edge, to the south of Raven's Wood, obtain an aether ray eye, and combine them to augment your sight. Search for the ghost Timeon identified as Sai'kkal the Elder.", sourceObjective = "Use an Aether Ray Eye with your Seer's Stone to reveal the raven cult ghosts. Search the Vortex Pinnacle for the spirit of Sai'kkal the Elder and question him about the book of the raven, then return to Arthorn Windsong.", progress = "<Arthorn looks at you hopefully.>\n\nWere you able to track down any information about the book?", completion = "Isn't it amazing that even among arakkoa, the cultists were considered heretics? That the traditional priests hated them enough to destroy their holy text is incredible! We must get our hands on that book, {name}.\n\nIt's the key to unraveling the mystery of the raven god and preventing him from taking over the Emerald Dream.\n\nPerhaps Morthis will finally agree to take me as a student if we succeed!", sourceObjectiveStatus = "unverified-source-field" }
quests[10981] = { id = 10981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexus-Prince Shaffar's Personal Chamber", progress = "Only the most steadfast and battle-hardened of adventurers will take me up on this offer, {name}. Should you wish to face the horrors of the second stasis chamber in the Mana-Tombs, I am able to synthesize a key. Bring me a mark of the Nexus-King and I will make it so.", completion = "As promised, here is the key to Shaffar's personal stasis chamber." }
quests[10982] = { id = 10982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Haramad", sourceObjective = "You have done much for the Protectorate and the Consortium, {name}. It is only fitting, then, that the first of our new keys goes to you. With this key you will be able to open Shaffar's personal stasis chamber at any time without having expended the key itself.\n\n\n\nIt is permanent and will be with you forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[10983] = { id = 10983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mog'dorg the Wizened", description = "Mog'dorg wise!  Him send Grok to city, look for help.  Bloodmaul clan need help.\n\nMog'dorg say, send powerful little ones to him at Blade's Edge Mountains.  Him stand on tower at Circle of Blood.  Mog'dorg wise!", sourceObjective = "Visit Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains.", completion = "Grok said that I am wise?  I don't know about that.\n\nPerhaps it is because I am the only one in my clan that is truly trying to save us from annihilation by the Bladespire clan, and Gruul and his sons, who are backing them.\n\nI hope that you have come to deliver us from certain doom, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10984] = { id = 10984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with the Ogre", description = "<V'eru's voice fills your mind with crystalline tone and clarity.>\n\nThere is an ogre down in the Lower City, pleading for the assistance of passersby.  They have all turned a deaf ear upon his plight.\n\nDo you think you might aid him?\n\nHis name is Grok, and he is sitting near the merchants to the southeast.\n\nThank you, {name}.", sourceObjective = "Speak with the Ogre, Grok, in the Lower City section of Shattrath City.", completion = "You help Grok?  Grok need help!  Bloodmaul clan need help!", sourceObjectiveStatus = "unverified-source-field" }
quests[10985] = { id = 10985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Distraction for Akama", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", sourceObjective = "Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.", progress = "<Xi'ri acknowledges your presence.>", completion = "<Xi'ri pulses with energy as you feel an object materialize in your hands.  It is the medallion you gave to A'dal on Akama's behalf, its power augmented by the naaru's magic.  The Sha'tar have entrusted you with the Medallion of Karabor, and with it access to the Black Temple.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10986] = { id = 10986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes in the Sky", description = "Locating the pieces of the Book of the Raven, if they survive at all, is going to be difficult. Our best hope is to use a keener pair of eyes than your own.\n\nDown in western Nagrand, on the eastern lip of the Twilight Ridge, Watcher Elaira studies the various bird species that make their home there. Visit her and see if she can help you harness avian sight to gather the pieces of the Book of the Raven.", sourceObjective = "Speak with Watcher Elaira at the Twilight Ridge in Nagrand.", completion = "<Elaira listens as you describe your search for the Book of the Raven and Arthorn's suggestion to use birds to locate the missing pieces of the tablet.>\n\nIt's an excellent idea and Nagrand is teeming with candidates, but which one to use?", sourceObjectiveStatus = "unverified-source-field" }
quests[10987] = { id = 10987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch A Sparrowhawk", description = "The wild sparrowhawks of Nagrand have the keenest sight of all the predatory birds here. But, because of their size, they've been pushed out of most areas by the larger windrocs.\n\nMost of the sparrowhawks nest here, on the Twilight Ridge. If you can catch one, I'll train it to spot the pieces of your buried tablet.\n\nIt's going to be difficult, though. The sparrowhawks are very skittish and will flee at your approach. I'd suggest cornering one or prowling to get close enough to cast your net.", sourceObjective = "Use the Sparrowhawk Net to capture a Wild Sparrowhawk and bring it to Watcher Elaira on the Twilight Ridge.", progress = "Did you catch one of the sparrowhawks?", completion = "Well done! I'm still in the process of getting the hawks to trust me, but I know enough about them to train this one for your needs.", sourceObjectiveStatus = "unverified-source-field" }
quests[10988] = { id = 10988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Raven Stones", description = "I've trained your sparrowhawk to respond to a specific whistle. When it hears the sound, the bird will fly to you and guide you to the location of the nearest tablet fragment. Arthorn sent word that the fragments you're looking for are buried in the Skettis area of southeastern Terokkar Forest, so the bird will wait for you there.\n\nWhen you've gathered all the stones, return the whistle to Arthorn and she will see to the animal's care and release.\n\nConvey my greetings to Arthorn when you see her.", sourceObjective = "Gather 8 Raven Stones from Skettis and bring them to Arthorn Windsong at Evergrove in Blade's Edge Mountains.", progress = "Did you recover enough of the Book of the Raven for me to reconstruct it?", completion = "<Arthorn accepts the fragments of the Book of the Raven from you and begins piecing them together.>\n\nSome of the characters have been worn away, but I should be able to make out most of this...", sourceObjectiveStatus = "unverified-source-field" }
quests[10989] = { id = 10989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mog'dorg the Wizened", description = "Mog'dorg the Wizened waits for you at top of da tower.  He tells me to look for a {race} {class} just like you.  You go speak with him about smart things.\n\nGo now, but don't tell no one.  It's a secret!", sourceObjective = "Speak with Mog'dorg the Wizened atop the tower where Chort is standing, just outside the Circle of Blood in the Blade's Edge Mountains.", completion = "Finally, Chort has sent me someone who looks like they might be able to help.  I am trying to save the Bloodmaul from annihilation by the Bladespire clan, and Gruul's sons, who are backing them.\n\nI trust that you will be the one to aid our secret society and deliver us into freedom.", sourceObjectiveStatus = "unverified-source-field" }
quests[10990] = { id = 10990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eagle's Essence", description = "The Book of the Raven tells us the raven's followers captured and bound the spirits of his rivals within stone shrines. A guardian was set to watch over each, lest the raven's enemies attempt to free them.\n\nThe first of the shrines is the eagle's, found in the hills to the south of Lake Jorune and west of Stonebreaker Hold in Terokkar Forest.\n\nThe tablet says that the eagle fought valiantly, but was overcome by a swarm of enemies. The armor and endurance of your bear form is well-suited to this fight.", sourceObjective = "Defeat the Guardian of the Eagle and obtain the Essence of the Eagle. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.\n\nIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement.", progress = "<The sparrowhawk seems to speak with Arthorn's voice.>\n\nDid you succeed in freeing the essence of the eagle spirit?", completion = "<Arthorn seems to feel the power in the recovered essence through the sparrowhawk's senses.>\n\nEven after thousands of years of captivity, the eagle's power remains strong. If the other essences are as strong as the eagle's, the raven god will be right to fear you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10991] = { id = 10991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Falcon's Essence", description = "<The bird speaks with Arthorn's voice.>\n\nThe second spirit bound by the raven's followers was the falcon.\n\nIt was subdued and imprisoned close to Skettis as a reminder to the raven-priests when they held power.\n\nOn the shores of Lake Ere'Noru, to the northwest of Skettis, you'll find the falcon's shrine.\n\nTo overcome the falcon's guardian, you'll need to use the falcon's strengths to your advantage. Use the speed and grace of your cat form to defeat the guardian before it reaches full strength!", sourceObjective = "Defeat the Guardian of the Falcon, obtain the Essence of the Falcon. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.\n\nIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement.", progress = "<Once again, Arthorn's voice issues from the sparrowhawk.>\n\nDo you have the falcon's essence?", completion = "<The sparrowhawk dutifully conveys Arthorn's words.>\n\nWell done, {name}. I'd feared that the falcon's prison had been destroyed in the explosion of Auchindoun. We're almost prepared to confront Anzu, {name}. I'd love to go with you, to be there when this self-styled \"god\" is cast back into the pit that spawned him!", sourceObjectiveStatus = "unverified-source-field" }
quests[10992] = { id = 10992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hawk's Essence", description = "<Arthorn's voice addresses you.>\n\nThe last, and strongest, of the spirits spoken of in the Book of the Raven is that of the hawk. It was imprisoned far from Skettis, in a shrine on a remote island southeast of Auchindoun.\n\nI believe this description best matches the island we know as Sorrow Wing Point.\n\nThe tablet describes the hawk's guardian as nearly invulnerable to the bird's claws. Forsake physical attacks and call down the fury of the stars to defeat this foe. Do not repeat the hawk's mistake.", sourceObjective = "Defeat the Guardian of the Hawk and bring the Essence of the Hawk to Arthorn Windsong at the Evergrove.", progress = "Did you overcome the hawk's guardian and win its essence?", completion = "Now that we have all the essences, Morthis Whisperwing must find a way to combine them into an amulet that you'll be able to use to challenge the raven god, draw him out of the Emerald Dream and defeat him. I'll be sending him my notes on the spirits with the hope that he'll realize the value of my insight.\n\nEach of the spirits has blessed a charm I've prepared for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10993] = { id = 10993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Cenarion Refuge", description = "Bring the essences to Morthis Whisperwing, along with word of our findings about the raven god.\n\nMorthis will know best how to use the essences and information in drawing Anzu out into the open. Make your way to him quickly, for there's no telling how long Clintar and the dreamwardens can withstand the raven's assault!\n\n<Arthorn grabs your arm before you turn to leave>.\n\nPlease, {name}, tell Morthis how much of a help I've been to you. I fear he will not see my hand in this work!", sourceObjective = "Bring Arthorn's Package to Morthis Whisperwing at Cenarion Refuge.", progress = "I've been waiting for word from Arthorn. What have you discovered?", completion = "<Morthis accepts the package, opens it to discover Arthorn's notes, and reads over them without commenting on the author.>\n\nOn one level, I'm relieved to finally know the identity of our enemy, but this Anzu is a being of considerable power. Knowing the nature and the name of your adversary is vital, but we are not yet ready to face him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10994] = { id = 10994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing the Moonstone", description = "If the essences are combined within a rare gemstone such as a Southfury moonstone, you'll be able to release them when you're prepared to challenge Anzu.\n\nThe only problem is that Southfury moonstones are only found on the Azshara side of the river, on the cliffs near the river's source.\n\nTragedy befell the last night elf party that sought the stone. Their boat is still anchored in the river near where they sighted the moonstone. Keep your eyes open and approach the site by land from the Azshara side.", sourceObjective = "Bring a Southfury Moonstone to Morthis Whisperwing at the Cenarion Refuge.", progress = "You look like you've been through quite an ordeal. Was the moonstone really that hard to find?", completion = "<Morthis seems torn, at once desiring to laugh at your story, and mindful of how close you came to losing the moonstone. He settles for staring at the glowing stone.>\n\nI'll get to work on infusing it with the bird spirit essences. Soon, you'll be prepared to challenge our enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[10995] = { id = 10995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grulloc Has Two Skulls", description = "To the east, at the terminus of Dragons' End, is the Cursed Hollow.  Therein, Grulloc, son of Gruul, plots his dimwitted schemes.\n\nI heard that one of his possessions was stolen from him through trickery.  Was that you?  Unfortunate that he was not slain in the process.\n\nIf we are to regain our freedom, I would have you take his most prized possession, a dragon skull from when he rejoiced in his father's slaying of the black dragonflight.  The only way you'll get the skull is to vanquish him.", sourceObjective = "Collect Grulloc's Dragon Skull.", progress = "Is Grulloc no more?", completion = "Indeed, it must have been a difficult struggle, {class}.  I feel greatly relieved now that he will not be breathing down our necks here.\n\nI will send this skull down to Chort for safekeeping.  I'm beginning to think that with your help, we might just pull this off.", sourceObjectiveStatus = "unverified-source-field" }
quests[10996] = { id = 10996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maggoc's Treasure Chest", description = "On the Razor Ridge, above and to the southeast, Maggoc patrols.  His father assigned him as the warden of the eastern mountain range, and he revels in terrorizing any creature that gets in his way.\n\nAs a son of Gruul, he must be done away with if my clan is to survive.  That's where you come in.\n\nMaggoc carries a treasure chest with him at all times.  Prove to me that he has been slain by bringing me his precious chest.  Feel free to keep whatever you find within it.", sourceObjective = "Collect Maggoc's Treasure Chest.", progress = "Do you have the chest?", completion = "You say it was empty?  Unfortunate, but you can see the mindless brutality that we're up against.\n\nWith the fall of Maggoc, we are one step closer to realizing my dream of a home for the ogres where we can determine our own destiny.", sourceObjectiveStatus = "unverified-source-field" }
quests[10997] = { id = 10997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even Gronn Have Standards", description = "Are you familiar with Shattrath City, {class}?  Above it to the northwest is a place called the Barrier Hills, which you can only get to upon a flying mount.\n\nOne of Gruul's sons, Slaag, exiled himself and took control of the Gordunni ogres that reside there.  Even at such a distance, we cannot afford to leave him in peace, lest he return when the rest of his brothers have been slain.\n\n{name}, you must travel there, and bring back his standard as proof that he has been dealt with.", sourceObjective = "Collect Slaag's Standard.", progress = "Do you return with Slaag's standard in hand?", completion = "What a relief that Slaag is gone.  No longer will we be threatened by the looming specter of his return!\n\nIf you do not mind, I will take the standard as a symbol of hope for all of the ogres of the mountains.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10998] = { id = 10998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim(oire) Business", description = "There is one more gronn to be slain: Skulloc Soulgrinder. He keeps himself hidden away, but there is a way to coax him forth.\n\nHe was trained by an ogre warlock known as Vim'gol the Vile, whose grimoire you must retrieve!\n\nVim'gol must be summoned by standing within a fire ring at his circle. Find Vim'gol's Circle in the mountains, to the northeast, near the Broken Wilds.", sourceObjective = "Collect Vim'gol's Vile Grimoire.", progress = "Have you summoned forth Vim'gol the Vile and taken the grimoire from his dead clutches?", completion = "I hesitate to even touch such a tainted thing of evil.  Yet read it we must if we are to glean what knowledge it contains and bring forth Skulloc from his hiding place.", sourceObjectiveStatus = "unverified-source-field" }
quests[10999] = { id = 10999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Shot, One Kill", description = "Bring me 8 trogg stone teeth." }
quests[11000] = { id = 11000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Soulgrinder", description = "The grimoire is the key to Skulloc's downfall.\n\nRead aloud from the book at Soulgrinder's Barrow to initiate the ritual.  An object known as the Soulgrinder will appear, as well as Skulloc's ghostly victims, who will try to destroy it.  You must keep them from doing so long enough to force Skulloc fully into the world.\n\nFind the barrow by heading north through the Daggermaw Canyon on the other side of the Circle of Blood.  It is on the right side before Gruul's Lair.\n\nBring back Skulloc's soul.", sourceObjective = "Collect Skulloc's Soul.", progress = "Have you taken Skulloc's soul yet?", completion = "It is over then.  You have freed us from the shackles of our enslavement to the Sons of Gruul.  You have given the Bloodmaul Clan a reprieve from certain extinction.\n\nWords cannot describe the extent of the debt that ALL of the ogres of the Blade's Edge Mountains, Bloodmaul and Bladespire alike, owe you, {name}.\n\nLook down, even now the ogres gather to pay you tribute.  Let Gruul and his puppet, the old king, Maulgar, cower within their lair.  Go to the ogres below as our new king!", sourceObjectiveStatus = "unverified-source-field" }
quests[11001] = { id = 11001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanquish the Raven God", description = "We must waste no time in dealing with the raven god. You must take the essence-infused moonstone to a place of great power in order to lure the god from the relative safety of the Emerald Dream.\n\nDescend into the Sethekk Halls and set the moonstone in the clutches of the raven's claw. You'll find it in the chamber before the talon king's hall.\n\nAnzu must be made believe that his followers have gathered to welcome him back into the world. Once he has manifested, show him no mercy!", sourceObjective = "Slay the Raven God and return to Morthis Whisperwing at Cenarion Refuge.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "What news from Sethekk Halls? Have you defeated Anzu?", completion = "It's good to see you again, {name}. Your triumph over the raven god counts for far more than any test or rite of passage that I might set for you.\n\nYou have truly proven yourself worthy of the knowledge guarded by the Druids of the Talon for countless generations.", sourceObjectiveStatus = "unverified-source-field" }
quests[11002] = { id = 11002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Magtheridon", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Alliance.\n\nReturn Magtheridon's head to Danath Trollbane at Honor Hold.", sourceObjective = "Return Magtheridon's Head to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", progress = "For the first time - in as long as I can remember - there is silence.", completion = "This defeat is not only a blow to Illidan, {name}. The Legion too reels... A pit lord commander has been defeated. The siege of Hellfire Citadel now holds no purpose for the Burning Legion. All of their efforts will undoubtedly be turned upon the Black Temple.\n\nRedemption comes for Illidan... and soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11003] = { id = 11003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Magtheridon", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Horde.\n\nReturn Magtheridon's head to Nazgrel at Thrallmar.", sourceObjective = "Return Magtheridon's Head to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "For the first time - in as long as I can remember - there is silence.", completion = "This defeat is not only a blow to Illidan, {name}. The Legion too reels... A pit lord commander has been defeated. The siege of Hellfire Citadel now holds no purpose for the Burning Legion. All of their efforts will undoubtedly be turned upon the Black Temple.\n\nRedemption comes for Illidan... and soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11004] = { id = 11004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World of Shadows", description = "Sky Commander Adaris was seriously injured during a Skettis incursion.  He's been in and out of consciousness since.\n\nI fear he has succumbed to a feverish delirium.  During brief lucid moments he demands that I prepare an elixir made from shadow dust carried by the arakkoa.  He seems to believe it will allow him to see into a \"world of shadows\" where the arakkoa's true leaders dwell.\n\nI do not believe this nonsense for a second, but I fear he won't rest until I obtain such an elixir.  Will you help?", sourceObjective = "Severin wants you to venture into Skettis and retrieve 6 Shadow Dusts from the arakkoa that dwell there.", progress = "Have you obtained the dust, {name}?", completion = "I thank you, {name}.  I will administer a small amount to the commander... to humor him.  You can keep the rest, perhaps you'll find a use for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[11005] = { id = 11005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Talonpriests", description = "Thank you for paying heed to my fevered rants.  All along we had been trying to identify and destroy the Skettis chain of command; we had learned of three clerics known as the talonpriests, but we'd never seen them with our own two eyes.  Now we know why.\n\nTalk to Severin to obtain more of the elixir he discovered.  Use the elixir to find and kill the three talonpriests: Ishaal, Skizzik and Zellek.  They're rumored to dwell in Veil Ala'rak, near the eastern shore of Blackwind Lake.", sourceObjective = "Obtain an Elixir of Shadows from Severin and use it to find and slay Talonpriest Ishaal, Talonpriest Skizzik and Talonpriest Zellek in Skettis. Return to Commander Adaris after completing this task.", progress = "Is the deed done, {name}?  I'd kill those blasted birdmen myself if it weren't for my injuries.", completion = "You've done well, {name}.  You've dealt a tremendous blow to the enemy by slaying the talonpriests.", sourceObjectiveStatus = "unverified-source-field" }
quests[11006] = { id = 11006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Shadow Dust", progress = "It looks like the commander was not delirious after all.  Bring me more dust and I'll prepare another elixir for you.", completion = "Keep bringing the dust to me.  I'll prepare as many elixirs as you need.\n\nCommander's orders." }
quests[11007] = { id = 11007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kael'thas and the Verdant Sphere", description = "The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael'thas Sunstrider. What secrets could it hold?\n\nPerhaps A'dal in Shattrath City could make sense of the item.", sourceObjective = "Take the Verdant Sphere to A'dal in Shattrath City.", progress = "You heard my call? Yes...", completion = "<A'dal's thoughts intermingle with your own.>\n\nThe sphere... Strange. Did you know that he lived? Yes. It is here - in the sphere itself. Maimed for certain. He calls to a higher power now. No, not Illidan.\n\nHigher.\n\nKil'jaeden the Deceiver comes...\n\nNot here...\n\n<A'dal points your mind elsewhere.>\n\nAzeroth. Unknown.\n\nRest. Your brothers and sisters will retake Tempest Keep now.\n\n<A'dal hums a song of battle.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11008] = { id = 11008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fires Over Skettis", description = "You think you have what it takes to be part of the Skyguard?  We'll have to see how you handle yerself in the air.\n\nThe arakkoa are breeding a gargantuan variety of their attack pets and are using it against our scouts.  I want you to take these blasting charges and use them to destroy hatcheries above the arakkoa's dwellings.  Avoid the monstrous kaliri guarding the hatcheries.  They'll knock you off your mount before you know what hit you.", sourceObjective = "Seek out Monstrous Kaliri Eggs on the tops of Skettis dwellings and use the Skyguard Blasting Charges on them. Return to Sky Sergeant Doryn.", progress = "Did you finish your assignment yet?", completion = "Excellent job, {name}!  That'll show those bird men the meaning of air superiority!", sourceObjectiveStatus = "unverified-source-field" }
quests[11009] = { id = 11009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Heaven", description = "Now that you have delivered us from bondage, we can begin the process of reunifying the clans.  This will take some time; old grudges are difficult to overcome.\n\nBut more pressing, you must go to Ogri'la in the heavens above to the west.  You must defend it, and us, from those forces above that the gronn used to protect us from: ethereals, demons, and worst of all, the black dragonflight.\n\nWhen you find ogre heaven, seek out the wisdom of Chu'a'lor on how best to proceed.", sourceObjective = "Mog'dorg the Wizened has asked you to speak with Chu'a'lor at Ogri'la in the Blade's Edge Mountains.", completion = "Mog'dorg sent a message ahead, saying that I should expect you.  I am glad that you came.\n\nWith the Sons of Gruul destroyed, it is only a matter of time - a short amount at that - before the various inhabitants of this mountain terrace, and the one to the north, decide to prey upon our ogre brothers down below.\n\nI trust that you will help us to prevent that, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11010] = { id = 11010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombing Run", description = "You have a flying mount... so what!  You think you have what it takes to use it properly?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nYou want to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", sourceObjective = "Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.", progress = "You take out their stacks of fel cannonballs yet?", completion = "Well, well, well, I guess you had it in you after all.  Good work.  Maybe Old Man Keller was wrong about you after all.\n\n<Sky Sergeant Vanderlip smirks.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11011] = { id = 11011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eternal Vigilance", description = "Your defeat of Anzu, the raven god, is truly a remarkable accomplishment. He may not abandon his quest to return to Outland, I fear.\n\nAs long as he has followers here, he will attempt to rise again. Keep the essence-infused moonstone with you in case we have not heard the last of Anzu.", sourceObjective = "Speak with Morthis Whisperwing to receive an Essence-Infused Moonstone.", completion = "Keep the moonstone with you, {name}. If you suspect that Anzu is gathering his strength to attempt another return to this world, use it to defeat him once again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11012] = { id = 11012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Oath of the Netherwing", sourceObjective = "Our lands are lost. Our children stolen in the night, forced into slavery - or worse...\n\n<Mordenai's voice tenses.>\n\nThe time is now, my ally. The time to retake what was once ours has come! You have proven yourself a capable combatant and compassionate soul.\n\nWill you swear to assist the Netherwing Dragonflight in retaking our lands and rebuilding our homes? Will you swear to watch over the flight and allow the bloodline to be born anew? Swear this and let us battle for our home and our loved ones!", sourceObjectiveStatus = "unverified-source-field" }
quests[11013] = { id = 11013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service of the Illidari", description = "Netherwing Ledge... What was once a bastion of sanctuary for the Netherwing is now home to the Dragonmaw. While the orcs may have control of our territory, our magic there is still strong. Strong enough to cloak your true identity and allow you to infiltrate the ranks of Dragonmaw.\n\nI have prepared this letter for you to present to their leader, Overlord Mor'ghor. Fly headlong into the maw of our enemy and seek out Dragonmaw Base Camp to start your new life as a fel orc of Illidan Stormrage.", sourceObjective = "Travel to Netherwing Ledge and deliver the Illidari Service Papers to Overlord Mor'ghor at Dragonmaw Base Camp.", progress = "<Mor'ghor grunts.>\n\nYou're late...", completion = "<Mor'ghor reads the letter and laughs.>\n\nA death knight? You couldn't shine the boots of a death knight, maggot.\n\n<Mor'ghor looks you over.>\n\nBut yes... You might be able to work your way up to peon. At the worst, I'll toss you into the pit and leave you to die...", sourceObjectiveStatus = "unverified-source-field" }
quests[11014] = { id = 11014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter the Taskmaster", description = "<Mor'ghor crumples up the service letter and tosses it aside.>\n\nAlright grunt, first things first. If you're gonna join my beloved Dragonmaw army, you'll need to work. Everyone works up here on the ledge. Get a job and don't screw it up and I'll see if there might be something more interesting for you to do later.\n\nGo talk to Taskmaster Varkule Dragonbreath. He's standin' in the middle of town. He'll assess your skills and assign work as he sees fit.\n\nNow get out of my face!", sourceObjective = "Speak with Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp.", completion = "Varkule gonna set you up right, grunt. You get your choice of one job best suited to your skills and Netherwing crystal collection. You'll be required to fill your work orders once per day.\n\nYeah, it's a bunch of crap jobs but even the ascendants started out as peons.", sourceObjectiveStatus = "unverified-source-field" }
quests[11015] = { id = 11015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netherwing Crystals", description = "No good at nothin'? That's fine. Even lunkheads like you can be used around here. Just find creatures on the ledge and kill 'em. Sometimes they'll have nether crystals on their carcasses. Gather those and bring 'em back to me and I'll consider your work order for the day complete.", sourceObjective = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 30 Netherwing Crystals.", progress = "Nether crystals are used for lots of things. Mainly makin' weapons and armor...", completion = "You're done for today, kid. Come back tomorrow if you're still alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11016] = { id = 11016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethermine Flayer Hide", description = "A skinner, eh? Well you'll find plenty to skin here! You gotta search for flayers around crystal formations. Take 'em down and take their hides. Sometimes they'll have a hide worth keepin'. Bring those to me.", sourceObjective = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 35 Nethermine Flayer Hides.", progress = "We use the flayer hides for armor lining and structural tarps.", completion = "You're done for today, kid. Come back tomorrow if you're still alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11017] = { id = 11017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netherdust Pollen", description = "A flower picker?! Hilarious... Unfortunately, our mages and shaman need your services. The netherdust bushes that grow on this ledge have special pollen that is apparently very useful in their magical dealings. Bring me that stuff and I'll consider your work order complete.", sourceObjective = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 40 Netherdust Pollen.", progress = "Like I said, netherdust pollen is used by our spell casters.", completion = "You're done for today, kid. Come back tomorrow if you're still alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11018] = { id = 11018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethercite Ore", description = "A miner!\n\n<Varkule salutes.>\n\nAn orc after my own heart! That's how Varkule got his start - minin'! There ain't nothin' better than getting down and dirty in the mines, is there?\n\nNow get out there and find those nethercite deposits. Strip 'em for all their worth and bring me back the ore.", sourceObjective = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 40 Nethercite Ore.", progress = "Gug over there is gonna use the ore to reinforce our weapons and armor.", completion = "You're done for today, kid. Come back tomorrow if you're still alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11019] = { id = 11019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Friend On The Inside", sourceObjective = "Didn't think we'd leave you to face the fel orc army by yourself, did you?\n\n<Yarzill's eyes flicker a translucent blue.>\n\nAye, we are here with you, {name}. For every service you perform for the fel orcs in your quest to reclaim Netherwing lands, we'll be at your side to make sure that they suffer a sufficient setback.\n\nYou'll need to keep a low profile so as not to draw any unwanted attention to yourself during your sabotage missions.", sourceObjectiveStatus = "unverified-source-field" }
quests[11020] = { id = 11020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slow Death", description = "The Dragonmaw have peons stationed at nearly every crystal formation up here. While the outright slaying of them would draw far too much unwanted attention to you, there is a way that we can thin their numbers and remain below the suspicious eyes of Mor'ghor.\n\nVenture into the wilds of Shadowmoon Valley and slay the tainted wildlife. Take from them their corrupt fel glands. Use those fel glands with this mutton that I'll give you near the peons. They'll take one bite and fall deathly ill!", sourceObjective = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to use Yarzill's Mutton in conjunction with Fel Glands to poison 12 Dragonmaw Peon Camps.", progress = "It is dirty work, {name}.", completion = "<Yarzill speaks in a low whisper.>\n\nExcellent work, {name}. Lay low for now. Come back to me tomorrow and we can do it again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11021] = { id = 11021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishaal's Almanac", description = "This mysterious tome was on Talonpriest Ishaal's body.  It contains arcane symbols and charts of celestial bodies beyond your comprehension.\n\nAll writing is in a language you don't understand; likely an ancient version of the arakkoa written tongue.  Perhaps you should bring this to Sky Commander Adaris.", sourceObjective = "Bring Ishaal's Almanac to Sky Commander Adaris north of Skettis.", progress = "You've something to show me?", completion = "What have you brought to me?  I can't make out the writing on this tome, {name}... my loss of blood... must've blurred my vision.", sourceObjectiveStatus = "unverified-source-field" }
quests[11022] = { id = 11022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Mog'dorg", description = "<King/Queen> {name}!  You speak with Mog'dorg the Wizened before you leave and go to Ogri'la!", sourceObjective = "Speak with Mog'dorg the Wizened. He stands atop the tower on the east side of the Circle of Blood in the Blade's Edge Mountains.", completion = "My good man, I am glad that you have decided to speak to me again before leaving.", sourceObjectiveStatus = "unverified-source-field" }
quests[11023] = { id = 11023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomb Them Again!", description = "We're still having problems with those flak cannons, {name}.\n\nDon't get me wrong -- I think that you did an outstanding job the last time out -- but, that doesn't change the fact that those damned demons seem to be replenishing their ammo supplies faster than we can knock them out.  And that means we're having a hell of a time getting our people through there, not to mention the risk those demons pose to Ogri'la.\n\nWhat do you say?  Want to take another shot at it?", sourceObjective = "Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.", progress = "How goes the bombing run?", completion = "Outstanding work, {name}!  I'd have you back up in the air and bombing them again, but policy around here is to make sure that our pilots get plenty of R&R.  Sorry, I don't make the rules, but I sure as hell enforce them!\n\nSee you again tomorrow, Ace!", sourceObjectiveStatus = "unverified-source-field" }
quests[11024] = { id = 11024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ally in Lower City", description = "There is an arakkoa in Lower City by the name of Rilak...  He can be trusted.  Take the book... to him.\n\n<Adaris drifts into unconsciousness as he returns the book to you.>", sourceObjective = "Bring Ishaal's Almanac to Rilak the Redeemed in the Lower City section of Shattrath City.", progress = "You have the smell of Skettis on you!  Explain yourself!", completion = "This cannot be... this belonged to a talonpriest once.  How did you ever come across it?", sourceObjectiveStatus = "unverified-source-field" }
quests[11025] = { id = 11025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crystals", description = "When prepared correctly, the crystals of the mountains exhibit strange powers, such as the clarity of mind that we have found here in Ogri'la.\n\nAll of the creatures atop the mountains covet the crystal shards and use them to further their own goals.  An economy has even sprung up around them.\n\nTo assist us, you must first learn about the Apexis shards.  Bring me some.  In addition to the creatures here having them, they can sometimes be found where the flayers dig at the larger crystals.", sourceObjective = "Chu'a'lor has tasked you with gathering 5 Apexis Shards. Bring them to him at Ogri'la atop the Blade's Edge Mountains.", progress = "As you come to understand the shards and crystals, you will be better able to assist us in protecting ourselves and our ogre brethren below.\n\nThe shards themselves get their name from an ancient and now-extinct arakkoan civilization, which used to live atop the mountains here.\n\nDo you have the shards with you?", completion = "<Chu'a'lor's left head begins to speak.>\n\nThese will do fine.\n\nRemember, {name}, the value of the shard is not in what it can purchase for you.  It is not even in what it can potentially do for you when properly forged, though there is some debate over that.\n\n\n\nThe true value is in the journey to attain the shard.", sourceObjectiveStatus = "unverified-source-field" }
quests[11026] = { id = 11026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banish the Demons", description = "You've arrived at the perfect time, friend!  We are in need of assistance.  In return, you will receive something very rare, which will help us both in the end.\n\nWe're not a violent ogre any longer, but the demons nearby threaten to overrun us and the Skyguard.  The problem with demons is that, once killed, they come right back in new bodies!\n\nBut, if you use this crystal to summon a banishing portal, when they die near it, their essences will be drawn in and banished back from whence they came!", sourceObjective = "Use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror.", progress = "We trust that you've used the banishing crystal to send a whole slew of those Burning Legion things packing?!", completion = "That'll teach them!  And, of course, now for your reward.\n\nThe demons of Forge Camp: Wrath, to the north, have created a special transporter on their southern border.   This experimental gate is being used to expand the forge camp, and we don't think we need to tell you how that will effect us if they expand too far.\n\nHowever, if we were you, we'd take this darkrune over to Gahk, and ask him how you can help.  Just take it easy on him, {name}.  Like you, he's new here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11027] = { id = 11027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yous Have Da Darkrune?" }
quests[11028] = { id = 11028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Countdown to Doom", description = "This almanac presages the return of Terokk, the most powerful and terrible Skettis king in arakkoa history.\n\nI always believed this to be the mere legend, {name}.  The return of the talonpriests and your recovery of this tome indicate otherwise.\n\nWith each day, Terokk comes closer to returning to full strength.  Your only chance is to bring him to our world prematurely.  Return to Skettis and speak to Adaris about this.  Let us hope he has the wisdom to do the right thing.", sourceObjective = "Return to Sky Commander Adaris at Blackwind Landing in Terokkar Forest with the news about Terokk's return.", completion = "The arakkoa seek to bring Terokk back beyond the veil of time and Rilak... wants to find a way to accelerate the process?  Is he out of his mind?\n\n<Adaris lays back down as his strength fades.>\n\nYou've done your duty, {name}.  It is time you let my men take over from here.  This has become a purely military matter.", sourceObjectiveStatus = "unverified-source-field" }
quests[11029] = { id = 11029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shabby Disguise", description = "Open the package, {name}.  It is a disguise.  It doesn't look very convincing, does it?\n\nI craft them for ethereal smugglers in search of rare books.  There is an arakkoa scribe who dwells in the central island in Skettis, Terokk's Rest; his name is Sahaak.  He is old and nearly blind.\n\nUse the disguise to speak with him and obtain the book known as the Adversarial Bloodlines.  Be careful, {name}.  The disguise won't fool the other arakkoa.", sourceObjective = "Use the Shabby Arakkoa Disguise to obtain the Adversarial Bloodlines from Sahaak and return to Hazzik.", progress = "The book, {name}.  Have you obtained it?", completion = "Excellent!  This book catalogs the descendants of Terokk's ancient enemies.  It is prophesied that their demise will be followed by Terokk's return.", sourceObjectiveStatus = "unverified-source-field" }
quests[11030] = { id = 11030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Boy Wants To Be A Skyguard Ranger", description = "{class}, we've got a problem -- we have lots of sons.  And ever since the Skyguard moved in nearby, all our sons ever talk about is joining their ranks.\n\nAs a proud father, we want them to have every advantage for when they apply.  So, would you go to the fel crystalforge at either forge camp to the north or south, and procure a magic flask for our sons?  You can't miss their green smoke.\n\nWe think that they take ten apexis shards to make.  We'd give you the shards, but we don't have any at the moment.", sourceObjective = "Collect an Unstable Flask of the Beast.", progress = "You have that magic flask, yet?  It will mean the world to little Torkus Jr.", completion = "You're a lifesaver, {name}.  Our boys are going to be so excited to hear the news!\n\nOK, so one down and one to go.  We did tell you about the other magical flask that they're going to need, didn't we?", sourceObjectiveStatus = "unverified-source-field" }
quests[11031] = { id = 11031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archmage No More", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
quests[11032] = { id = 11032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protector No More", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
quests[11033] = { id = 11033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assassin No More", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
quests[11034] = { id = 11034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restorer No More", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
quests[11035] = { id = 11035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Not-So-Friendly Skies...", description = "On the northeast edge of this island exists a dock used for the packaging and transport of Netherwing crystals and relics. Dragonmaw Transporters transport the goods from the dock to Dragonmaw Fortress while Dragonmaw Ascendants guard the ground from any would-be attackers.\n\nThis leaves one opening for you to make a strike at the Dragonmaw: The Dragonmaw Skyway.\n\nFly to the shattered islands of the Dragonmaw Skyway and ambush the transporters that use the route. Recover our stolen relics!", sourceObjective = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover 10 Netherwing Relics.", progress = "Dead orcs tell no tales, {name}. Make sure those Dragonmaw transporters do not escape.", completion = "<Yarzill whispers.>\n\nYou are doing the Netherwing a great service, {name}. Slowly, we will topple the Dragonmaw. From the inside a disease now grows - a disease with no cure...\n\nReturn to me tomorrow if you are interested in more work at the Dragonmaw Skyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[11036] = { id = 11036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of This World Produce!", description = "I'll be the first to admit I'm not quite sure what this order is for, but Rocket-Chief Fuselage's instructions were very specific -- only the very best fruit, preserved to survive a long voyage and sealed against the elements.\n\nThere were other specifications, zero-gravity this and low pressure that. I don't pretend to understand it, but the price is right, so he'll get his superfood. Bring this crate to him up at Area 52. After crossing into Netherstorm, keep following the road until you see the town.", sourceObjective = "Bring the Preserved Fruit to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "Is that the delivery from Old Orok?", completion = "<The chief inspects the crate's contents.>\n\nEverything looks good here. That's one more thing to cross off the list. Now all we need to do is get the rocket off the ground!", sourceObjectiveStatus = "unverified-source-field" }
quests[11037] = { id = 11037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Vision", description = "I've had a most unusual vision, {name}, and I don't know quite what to make of it. I've seen an arrow, an immense arrow, riding into the sky on a trail of fire. Such a feat is trivial for a skilled mage, but somehow I know the arrow I saw is not the product of magic.\n\nIt will be unlike anything the people of Azeroth have ever achieved. You must seek out the people working on this, {name}. Lend them your help, for without it, their efforts may yet fail.", sourceObjective = "Speak with Rocket-Chief Fuselage at Area 52.", completion = "<The chief listens as you describe the seer's vision.>\n\nWell, I don't know about any of that, but we could certainly use your help around here. Behold the rocket behind me! That's the X-52...\n\nIsn't it the most beautiful thing you've ever seen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11038] = { id = 11038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assist Exarch Orelis", description = "Not long ago, High Priestess Ishanah sent a small group of anchorites to Netherstorm, under the command of Exarch Orelis. They were to investigate the activities of Kael'thas and his minions, but we haven't received any reports of their findings yet.\n\nI worry that our presence in the area might not be strong enough to carry out the mission. I'm certain that the exarch could benefit from your knowledge and experience. Are you willing to travel to Area 52 and assist him?", sourceObjective = "Speak with Exarch Orelis at Area 52.", completion = "So you're here to help us determine exactly what Kael'thas is planning? Your help is most welcome. Netherstorm is crawling with blood elf agents whose activities threaten to tear the land asunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11039] = { id = 11039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Spymaster Thalodien", description = "Some time ago, Voren'thal dispatched a small team to Netherstorm to investigate the activities of Kael'thas. Our leader has the utmost confidence in Spymaster Thalodien and his compatriots, and has decided to honor his request for reinforcements.\n\nThalodien's report was brief, but clear that he's encountered something of great importance. Report to him at Area 52 and assist him in any way possible, {name}.", sourceObjective = "Report to Spymaster Thalodien at Area 52.", completion = "<A brief look of disappointment crosses the spymaster's face.>\n\nI was hoping for at least a squad, but if Voren'thal saw fit to send only you, then I will adjust my plans accordingly.", sourceObjectiveStatus = "unverified-source-field" }
quests[11040] = { id = 11040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts for the Rocket-Chief", description = "You can count on one hand the number of times I've collaborated with a goblin. We're far more likely to be in competition with them, but when I received Rocket-Chief Fuselage's request, I just couldn't refuse him.\n\nThis crate is full of parts I'm not using here, but that the rocket-chief might be able to put to use on his project. Would you be kind enough to deliver them if you're on your way to Area 52?\n\nWho knows, maybe some fine gnomish parts could keep his creation from exploding!", sourceObjective = "Bring Bossi's Spare Parts to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "That crate has the look of a master gnomish engineer about it. Did Bossi send you?", completion = "I don't even know what some of these parts do! I'm certain I'll find a use for some of them, but I never suspected I'd have to learn to think like a gnome!", sourceObjectiveStatus = "unverified-source-field" }
quests[11041] = { id = 11041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Job Unfinished...", description = "In the name of our great master... For the glory of Illidan!\n\nBy order of Overlord Mor'ghor, the great plateau of Netherwing Ledge is to be secured. With all Netherwing drakes captured or forced off of the land, rock flayers are running rampant and threatening crystal harvesting operations.\n\nDestroy them all, their den mother and her consort, Arvoar.\n\nMor'ghor commands it!\n\n<It would appear that this orc failed to take the plateau. It is time to prove your worth to Mor'ghor!>", sourceObjective = "Slay 10 Overmine Flayers and Barash the Den Mother. Return to Overlord Mor'ghor at the Dragonmaw Base Camp should you succeed.", progress = "Who dares approach Mor'ghor? This had better be important.", completion = "So from the remains of one of my own overseers you recovered the command and took matters into your own hands? You have managed to impress Mor'ghor. Well done...", sourceObjectiveStatus = "unverified-source-field" }
quests[11042] = { id = 11042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mystifying Vision", description = "A strange vision haunts me, {name}. I see a continuous cloud of smoke ascending toward the sky, left in the wake of a giant fire moving ever faster away. It is not a natural phenomenon, nor a creation of evil; that much I know.\n\nI have no knowledge of what it looks like, save that it is the product of the labor of many. Yet, without more hands, it may never come to be.\n\nTravel to Netherstorm, {class}. Locate those responsible for this creation and offer them your aid.", sourceObjective = "Speak with Rocket-Chief Fuselage at Area 52.", completion = "<The chief listens as you describe the seer's vision.>\n\nWell, I don't know about any of that, but we could certainly use your help around here. Look at the behemoth behind me. That's the X-52...\n\nIsn't it the most beautiful thing you've ever seen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11043] = { id = 11043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building a Better Gryphon", description = "I've heard that the Wildhammer dwarves maintain a gryphon roost at their fortress down in southern Shadowmoon Valley. If you're going down there, would you speak to them on my behalf? I have some ideas on how to improve their gryphons!\n\nWhy stop at armoring them when you could attach an altimeter, a rear view mirror, and rocket? Imagine how fast you could go with one of those babies strapped to your gryphon's back! I'll call it the TurboGryphon 8000!", sourceObjective = "Speak with Brunn Flamebeard at Wildhammer Stronghold in Shadowmoon Valley.", completion = "<Brunn's face reddens until its color is indistinguishable from his beard.>\n\nHe wants to do WHAT to my gryphons?\n\nIf that little pipsqueak puts anything other than a saddle on them, I'll personally travel up to Blade's Edge and stuff that rocket o' his down his throat!", sourceObjectiveStatus = "unverified-source-field" }
quests[11044] = { id = 11044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of Destruction", description = "A vision of cataclysm often disturbs my rest -- a rain of green fire falling to the earth, felling the valiant defenders of a mighty fortress. It has haunted me for weeks now, although I have only recently come to understand its meaning.\n\nTo the far east, in Shadowmoon Valley, the Wildhammer dwarves endure constant attacks from the Burning Legion and numerous other foes. They fight bravely, but without relief, their enemies will triumph. Go to their side, {name}. Help them in their fight.", sourceObjective = "Speak with Wing Commander Nuainn at Wildhammer Stronghold.", completion = "A vision, you say? I don't care if he saw it in a vision, read it in a letter, or heard it from the mouth of a pit lord. He was dead on! What matters is that you're here, friend, and we need all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[11045] = { id = 11045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorus the Judicator", description = "The history of Shadowmoon Valley is a long and troubled one. Few delve into it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Zorus the Judicator searches for the truth about the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which he would welcome help, I'm sure.\n\nIf you should venture into the valley, look for Zorus at Wildhammer Stronghold, in the central portion of the valley's southern region.", sourceObjective = "Speak with Zorus the Judicator at Wildhammer Stronghold.", completion = "Fantei speaks the truth and I would welcome your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11046] = { id = 11046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Apothecary Hildagard", description = "The history of Shadowmoon Valley is a long and troubled one. Few study it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Chief Apothecary Hildagard's research delves into the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which she would welcome help, I'm sure.\n\nIf your travels bring you there, seek Hildagard at Shadowmoon Village, in the northwestern reaches of the valley.", sourceObjective = "Speak with Chief Apothecary Hildagard at Shadowmoon Village.", completion = "Fantei has a good memory. It's been months since I was last in Shattrath to buy reagents. He's right, though. I could use the help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11047] = { id = 11047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apprentice's Request", description = "As an apprentice wind rider master, one of my tasks is to care for the beasts when they're not flying. The problem is that we have so few here, there's very little downtime for any of them.\n\nI'm afraid we'll work them all to death if we don't receive any replacements. There's a large stable down in Shadowmoon Village, in western Shadowmoon Valley. Dama Wildmane oversees the wind rider care and training there.\n\nWould you speak with her on our behalf and let her know about our situation?", sourceObjective = "Speak with Dama Wildmane at Shadowmoon Village in Shadowmoon Valley.", completion = "<Dama listens to Agadai's request.>\n\nI can't guarantee that there will be any wind riders available, but I'll see what I can do. As it is, we're having trouble keeping up with the demands of other buyers and outposts.", sourceObjectiveStatus = "unverified-source-field" }
quests[11048] = { id = 11048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kroghan's Report", description = "My original orders were to remain in Garadar for a short time, then continue on and report to Blood Guard Gulmok at Shadowmoon Village. What I've seen in my time here is that Garadar could benefit from a long term Horde liaison.\n\nI know that Blood Guard Gulmok needs all the troops he can get, but I know he'll understand that my mission here isn't yet complete. Travel to Shadowmoon Village, in northwestern Shadowmoon Valley, and inform Blood Guard Gulmok of my delayed arrival.", sourceObjective = "Speak with Blood Guard Gulmok at Shadowmoon Village.", completion = "<Gulmok grumbles upon hearing of Kroghan's decision.>\n\nI understand his point of view, but we need warm bodies in the trenches here too! The Legion's bombarding us with infernals day and night. If Kroghan's going to be delayed, you can take his place on the field!", sourceObjectiveStatus = "unverified-source-field" }
quests[11049] = { id = 11049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Netherwing Egg Hunt", description = "Should you discover any Netherwing eggs while exploring, bring them to me.\n\nBe warned, a Netherwing egg is a rare discovery. Do not become frustrated if you cannot locate one. These Dragonmaw have been very thorough in collecting most of them and shipping them off to parts unknown.\n\nEggs might be found on creatures of the island, near crystal formations, in the mines, or even inside a nethercite node or netherdust bush.\n\nKeep a low profile. We don't need Mor'ghor catching wind of your actions.", sourceObjective = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover a Netherwing Egg.", progress = "How goes the egg hunt?", completion = "Neltharaku will be most pleased, {name}. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[11050] = { id = 11050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Accepting All Eggs", progress = "We don't need those eggs to get into the wrong hands, {name}. Bring me any additional eggs that you may find.\n\nJust remember to keep a low profile and avoid raising suspicion!", completion = "You are a true hero, {name}." }
quests[11051] = { id = 11051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banish More Demons", description = "If we know the demons, and we do because we've studied them extensively, they're fast at work repairing any damage that has been done to their precious transporter.\n\nSo, if you want a chance at another darkrune, take our banishing crystal back out there and eliminate more demons.  Besides, you want to help us to lessen the threat that the demons pose, yes?\n\nWe said \"chance\" because the process we use yields mixed results.  You might get a darkrune, or you might get something else entirely.", sourceObjective = "Use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror.", progress = "A seasoned pro such as yourself shouldn't be having any difficulty banishing demons.  You're not having any difficulties, right, {race}?", completion = "We wish the process of creating a darkrune was foolproof, {name}.  Alas, it is not.  Please, take this bag and look in it to see what we've wrought today.  We couldn't bear to look ourselves.\n\nRemember, if you get a darkrune, take it to Gahk to exchange for a crystalforged darkrune.  Then you'll be able to once more bring down Shartuul's transporter.\n\nOh, and {name}, don't forget to come by again tomorrow and pickup the banishing crystal.  There are always more demons to be banished.", sourceObjectiveStatus = "unverified-source-field" }
quests[11052] = { id = 11052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akama's Promise", description = "<Akama inserts the crystal into the medallion in his hand.>\n\nI am not as strong as I once was, {name}.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.\n\nTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A'dal in Shattrath City.", sourceObjective = "Bring the Medallion of Karabor to A'dal in Shattrath City.", progress = "<A'dal notices your approach and a warm light embraces you.  A'dal seems to know you have something for him.>", completion = "<As you give the medallion to A'dal, it disappears into his being in a flash of light.>\n\n<You are briefly shown a glimpse of a moment... perhaps in the future.  You see Akama and Maiev coming out of the Warden's Cage, fighting their way to the Dark Temple.  A third figure shrouded in shadows is aiding them.  Upon closer inspection you notice that the figure is you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11053] = { id = 11053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Overseer!", description = "Rare it is that a peon survives for as long as you have. Rarer still is when a peon rises from the dregs to attain a new rank.\n\n<Varkule claps.>\n\nThe Overlord has called for you, grunt. A new rank awaits, no doubt.", sourceObjective = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "I have been following your activities closely, {name}. You have proven to be an invaluable asset to Dragonmaw. With that said, I am going to promote you to Overseer. With that rank comes new responsibilities that you must fulfill.\n\nRise, Overseer {name}! Rise and seek out those that need your assistance at the base camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11054] = { id = 11054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overseeing and You: Making the Right Choices", description = "So you're the new overseer, eh? Well there's one thing any good overseer needs and that's the proper disciplinary weapon. Before you can go out there and knock some sense into these peons you need to have your \"piece.\" Each overseer has to gather the materials required to make their own \"piece\" and you'll be no different.\n\nI'll need knothide leather and the hardened hide of Tyrantus. You'll find Tyrantus in Eco-Dome Farfield, located in the northern reaches of Netherstorm.", sourceObjective = "Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 10 pieces of Knothide Leather and 1 Hardened Hide of Tyrantus.", progress = "There's peons to be disciplined, {name}! Hurry it up!", completion = "ARRR! You might make it as an overseer after all. That oversized lizard has been the bane of many an orc!\n\n<Chief Overseer Mudlump begins to fashion the weapon.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11055] = { id = 11055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Booterang: A Cure For The Common Worthless Peon", description = "This is your booterang. There are many like it but this one is yours.\n\nAs an overseer you will use this booterang to sow terror into the hearts of defiant peons. Proper use of the booterang will instill obedience and ensure subservience.\n\nVenture forth to the crystal fields and discipline any peons that you see slacking off. Show them the might of the booterang!", sourceObjective = "Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to discipline 20 lazy Dragonmaw Peons. You will also need to return your Booterang.", progress = "It's all in the wrist, {name}.", completion = "A hard day's work! It pays off, though, doesn't it? Warms your heart seeing those worthless runts slavering over those crystals... Anyhow, that's all for today. Come back tomorrow for another round of booterang discipline.", sourceObjectiveStatus = "unverified-source-field" }
quests[11056] = { id = 11056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazzik's Bargain", description = "Do not draw attention to our conversation.  Adaris would not approve.\n\nI belong to the lowest caste of arakkoa, {name}.  During Terokk's rule I would've been sacrificed to the dark powers worshipped by his talonpriests.  If what you say is true and the talonpriests are seeking Terokk's return, then you must prevent them from succeeding - regardless of what your leader says!\n\nI've something to offer you that you'll find useful.  There is a package at my old dwelling in Upper Veil Shil'ak.  Bring it to me!", sourceObjective = "Obtain Hazzik's Package at his dwelling in eastern Skettis and return to him with it.", progress = "You've returned, {name}.  I was beginning to think you'd given up on me.", completion = "Excellent, {name}.  You will see that I'm true to my word.", sourceObjectiveStatus = "unverified-source-field" }
quests[11057] = { id = 11057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trouble Below", description = "We commend your zeal in wanting to help out here in Ogri'la, {class}.  However, we have a favor to ask of you before we can accept your assistance.\n\nDown below our brethren are enslaved to the Sons of Gruul.  Please, speak with Mog'dorg the Wizened, who is leading an ogre resistance against their gronn masters.\n\nSeek him out atop the tower on the eastern side of the Circle of Blood arena.", sourceObjective = "Speak with Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains.", completion = "You were sent from on high?  Truly my mission is blessed!  I am trying to save the Bloodmaul from annihilation by the Bladespire clan, and Gruul's sons, who are backing them.\n\nI trust that you will be the one to aid our secret society and deliver us into freedom.", sourceObjectiveStatus = "unverified-source-field" }
quests[11058] = { id = 11058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Apexis Relic", description = "Long ago a now-extinct sect of the arakkoa known as the Apexis lived here.  Remnants of their civilization are still present.  We call them apexis relics.\n\nWhat we know about them is that, when properly used, they grant a boon.  Each relic presents a colored sequence which, when the crystals are pressed in the correct order, leads through a series of levels, each harder than the last.\n\nAn apexis shard is needed to power the relic.  Return when you have attained the insight of the apexis vibration.", sourceObjective = "Gain Apexis Vibrations from an Apexis Relic.", progress = "Have you learned how to use the apexis relic yet?  Both we and the Sha'tari Skyguard just to the north are interested in what you learn about them.", completion = "<Chu'a'lor nods his heads at you in satisfaction at your accomplishment.>\n\nYou have a quick mind, {name}.  It took us much longer to successfully make use of the relic.\n\nNow that you know how, you can do so as much as you care to.  Just remember that they require an apexis shard to power them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11059] = { id = 11059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardian of the Monument", description = "You've figured out how to use the single-person relics, but as you may have seen, there are bigger ones, which they surround.\n\nThese larger apexis monuments function in much the same way, but they take 35 apexis shards to activate.\n\nOf greater concern to us are the guardians that are summoned through their use.  These crystal constructs turned on their arakkoan masters long ago, and now endanger Ogri'la.\n\nWe would ask that you destroy one and bring us proof.", sourceObjective = "Collect an Apexis Guardian's Head.", progress = "We abhor violence, but at least the construct that we have sent you against isn't a living being.\n\nSpeaking of which, do you have the head?", completion = "<Chu'a'lor beams at you with obvious respect.>\n\nNot only are we impressed with the mental alacrity of you and your friends, but we are indebted to you, as is all of Ogri'la and the Skyguard, for helping to protect our way of life here.\n\nAnd remember, {name}, at any time you can gather others and return to any of those larger apexis monuments to make use of them; as long as you have enough apexis shards to power it that is.", sourceObjectiveStatus = "unverified-source-field" }
quests[11060] = { id = 11060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crystalforged Darkrune", progress = "Da demons are making da Forge Camp: Wrath bigger.  Soon, dey be too big and crush us.  You crush dem first!\n\nShartuul's transporter is da key, but it protected by a magic shield and a demon called a degrader.  Us powerful warlock, and make special darkrune dat give you control of da degrader.  {race} give Gahkdarkrune, us give {race} crystalforged darkrune back.\n\nTake control of da degrader and possess as many of da demons dat come through da gate as you can ta stop dem!", completion = "Little {race}, remember, when you control da degrader, you use its hammer ta smash da warp-gate's shield and let loose da demon within.\n\nDen you crush dat demon and control it.  Den another demon come and you control it, until da eredar overseer come.\n\nDen you crush him too!!!" }
quests[11061] = { id = 11061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Father's Duty", description = "As to that other magical flask, it can only be obtained from one spot: Bash'ir Landing.  It's an ethereal base, and they aren't too friendly with outsiders, so it might be a little dangerous to obtain.\n\nWhere's Bash'ir Landing, you ask?  Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you'll eventually spot it.  The Bash'ir crystalforge itself is at the northeast corner of the landing.\n\nThank you for doing this, {name}.  It'll mean the world to our sons!", sourceObjective = "Collect an Unstable Flask of the Sorcerer for him.", progress = "That sorcerer's flask is sure to make my boys more intelligent than they already are, and that should help immensely with what they'll need to do once they're in the Sha'tari Skyguard.", completion = "We can't thank you enough, {name}!\n\nNow with these two flasks, unstable though they may be, we'll be able to send one of our boys north to the Skyguard Outpost.\n\nHere, just wait a moment and we'll call for one of them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11062] = { id = 11062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skyguard Outpost", description = "{name}, we were wondering if you might be willing to visit our friends just to the north at the Skyguard Outpost?\n\nSky Commander Keller and his Skyguard are here running missions for our mutual protection, and he's asked us to send along anyone that we feel would excel at helping out.\n\nThat would be you!\n\nHead up there as soon as you can, and please, give him our regards.", sourceObjective = "Speak with Sky Commander Keller at the Skyguard Outpost in the Blade's Edge Mountains.", completion = "Welcome ta the Skyguard Outpost!  I built it with me own hands ya know.\n\nYeah, the whole thing!\n\n<The sky commander looks serious.>\n\nSo, ye must be lookin' ta spoil for a fight if ye're here talkin' ta me.  It was kind of old Chu'a'lor ta send ye along.  We can always use fresh meat for the grinder around here.\n\nIf ye don't mind, I'd like ya ta start by having a talk with my sergeant across the way: Vanderlip.  Don't mind her tongue, though it be sharper than the greatsword she be carrying.", sourceObjectiveStatus = "unverified-source-field" }
quests[11063] = { id = 11063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earning Your Wings...", sourceObjective = "So you wanna join the Skybreakers, eh? You've certainly proven yourself an able Dragonmaw but that means nothing in the skies of Outland. The question has to be answered: CAN YOU FLY?\n\nAnd I don't just mean being able to mount up on a nether drake and delivering a shipment of crystals to the fort like those transporter scrubs. I'm talking about being the best... The top orc...\n\nOver to the west there are six riders. Defeat them all and I will grant you Skybreaker wings.", sourceObjectiveStatus = "unverified-source-field" }
quests[11064] = { id = 11064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: The Ballad of Oldie McOld", description = "Don't let the gray hair fool you, grunt. I'm still ten times the rider that you are! And don't go thinking that this old dog doesn't have any tricks up his sleeve.\n\nNow all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat.\n\nWe'll lift off as soon as you're ready.", sourceObjective = "Follow Murg \"Oldie\" Muckjaw while attempting to stay on your flying mount. Should you defeat Murg \"Oldie\" Muckjaw, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Pumpkins? Oh how the mighty have fallen... I am certain the other riders will prove to be much more challenging.", sourceObjectiveStatus = "unverified-source-field" }
quests[11065] = { id = 11065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrangle Some Aether Rays!", description = "Wanna help the Skyguard and Ogri'la?\n\nJust hear me out before you walk away, <hot stuff/girly>.  We're in need of remounts!  The bombing runs and missions to Bash'ir Landing have taken a toll on our mounts.\n\nThe aether rays that fly around Vortex Summit, and the Crystal Spine to the northeast, look like they'd do just fine.  You don't even have to bring them back here, though that would be nice.  Just break and rope them, and we'll track them down later.\n\nThink you can wrangle me up some?", sourceObjective = "Use the Wrangling Rope to capture 5 Aether Rays.", progress = "You wrangle me some aether rays yet?  You look like you might have some skill with rope, so it shouldn't take you too long.", completion = "Woo hoo!  Nice job, {name}!  Those rays are going to make excellent mounts!\n\nStick around kid... the Sha'tari Skyguard can always use a man of your obvious talents!", sourceObjectiveStatus = "unverified-source-field" }
quests[11066] = { id = 11066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrangle More Aether Rays!", description = "So, I hope that you're up to helping us wrangle up even more aether rays!  From what I can see, you're a natural with the rope!  And it's for a good cause, because not only do we get fresh mounts, but it helps us to protect Ogri'la, which the ogres appreciate.\n\nRemember, the aether rays fly around Vortex Summit, and the Crystal Spine to the northeast.\n\nThink you can wrangle me up some more?", sourceObjective = "Use the Wrangling Rope to capture 5 Aether Rays.", progress = "You're doing great work for us, {name}.  I want you to know that we really appreciate everything that you're doing to keep us stocked up in fresh mounts!", completion = "You continue to amaze me!  Tell you what... why don't you come back tomorrow and we'll let the rope cool off for now?\n\n<Khatie laughs.>\n\nThank you so much, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11067] = { id = 11067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Trope the Filth-Belcher", description = "Dragonmaw treat you right, {name}. Even a worn out cursed being like me is given a chance. Now if you want to prove your worth to the Skybreakers, you will have to defeat me.\n\nI'm going to shake you off my tail like a bad case of fleas...\n\nWe'll lift off when you are ready.", sourceObjective = "Follow Trope the Filth-Belcher while attempting to stay on your flying mount. Should you defeat Trope the Filth-Belcher, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Interesting... Your next match will undoubtedly prove much more difficult. Corlok is no slouch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11068] = { id = 11068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Corlok the Vet", description = "You are challenging ME? Don't make me laugh!\n\nYou're serious? Very well then! All you need to do is not die. You can manage to not die, right?? Even if I'm hurling skulls at you and flying circles around your pathetic riding skills?\n\nJust let me know when you're ready and we'll lift off.", sourceObjective = "Follow Corlok the Vet while attempting to stay on your flying mount. Should you defeat Corlok the Vet, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "The next two riders were the two top pilots that the dwarves and orcs of Azeroth had to offer. You stand no chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11069] = { id = 11069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Wing Commander Ichman", description = "Three years I spent in that hell hole. Three years a prisoner of war to the damnable Frostwolf Clan. Made to sit in their tower and listen to them endlessly whine about the bridge to Dun Baldar. About how it's \"unfair\" that blah, blah, blah, blah... War isn't fair! To hell with 'em all!\n\nThe minute I was freed I left that place forever and came here to start a new life. Now Mulv and I are vying for the top orc spot. If you want it, you're gonna have to go through me, scrub.\n\nWe go when you're ready.", sourceObjective = "Follow Wing Commander Ichman while attempting to stay on your flying mount. Should you defeat Wing Commander Ichman, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "I don't believe it! Mulverick is your next challenge. There's no way you'll survive that match.", sourceObjectiveStatus = "unverified-source-field" }
quests[11070] = { id = 11070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Wing Commander Mulverick", description = "Three years of blood, sweat and tears. Mostly tears... The amount of crying that a hardened soldier does when it comes down to all-out war is amazing!\n\n\"They're jumping into our tower with their horses!\" \"Why is their base so well defended?\" \"They're taking our relief hut, I'm going A.W.O.L.!\"\n\nWimps...\n\nI took the first train out of \"cry-town\" the minute the Dark Portal opened. Now I'm a top gun for the Dragonmaw. If you want to be top orc, you'll have to defeat me.\n\nWe go when you are ready.", sourceObjective = "Follow Wing Commander Mulverick while attempting to stay on your flying mount. Should you defeat Wing Commander Mulverick, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Well it looks like it's just you and the captain now, grunt. Good luck! You're gonna need it!", sourceObjectiveStatus = "unverified-source-field" }
quests[11071] = { id = 11071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Race: Captain Skyshatter", description = "You dare challenge Skyshatter? The world around you will fall into darkness as the heavens are torn asunder by my meteors.\n\nYou stand no chance, soldier. Yet it is your desire to die...\n\nI will entertain this morbid obsession if only to prove a point to any that might foolishly dream of making the same mistake.\n\nWe ride when you are ready!", sourceObjective = "Follow Captain Skyshatter while attempting to stay on your flying mount. Should you defeat Captain Skyshatter, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "I never dreamed any would be skilled enough to defeat Skyshatter. You do know what this means, right? You are now the top orc! You must defend your title.", sourceObjectiveStatus = "unverified-source-field" }
quests[11072] = { id = 11072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adversarial Blood", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.", sourceObjective = "Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile. Return to Hazzik at Blackwind Landing with a token from each.", sourceObjectiveStatus = "unverified-source-field" }
quests[11073] = { id = 11073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokk's Downfall", description = "I... I've turned a blind eye to your dealings with the arakkoa prisoner, {name}.  It looks like your instincts to cooperate with him were right.\n\nYou must understand... I would've faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world.\n\nTake the items that Hazzik prepared for you and go ahead with your plan.  I will command my men to back you up when the time comes.  I recommend that you bring a force of your own as well.  I fear you'll only get one chance at this.", sourceObjective = "Take the Time-Lost Offering prepared by Hazzik to the Skull Pile at the center of Skettis and summon and defeat Terokk. Return to Sky Commander Adaris when you've completed this task.", progress = "Is it done, {name}?  Has Terokk been defeated?", completion = "You've made us all very proud, {name}.  I'll send word of your deeds back to Shattrath.  The Skyguard will be forever in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11074] = { id = 11074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tokens of the Descendants", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book.  Gezzarak the Huntress, Garokk the Crystal Giant, the heretic known as Darkscreecher Akkarai and Vekkaz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa and burn them at the summoning circles all over Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.", sourceObjective = "Collect Time-Lost Scrolls from the time-lost arakkoa in Skettis and bring them to a Skull Pile inside a summoning circle in Skettis. Summon and defeat the descendants of Terokk's adversaries and return to Hakkiz with Akkarai's Talon, Garokk's Spine, Vekkaz's Scale and Gezzarak's Claw.", progress = "I require a token from each of the descendants of Terokk's greatest adversaries.  Only then will we be ready to summon Terokk.", completion = "Excellent!  Take this.  I've prepared this bundle with the items you obtained.  They will allow you to summon Terokk.\n\nBeware, {name}.  He is the most powerful arakkoa to ever exist.  Do not underestimate him!", sourceObjectiveStatus = "unverified-source-field" }
quests[11075] = { id = 11075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Netherwing Mines", description = "Your help is required at the Netherwing Mines, overseer {name}.\n\nTwo days ago our mining operations came to a grinding halt when we made a grim discovery. A miner was working in the depths of the mine and struck his pick upon an unusual crystal formation. Unfortunately, this crystal formation was attached to a very angry nether dragon. The beast woke from its slumber and annihilated all of our workers.\n\nReport to the Mistress of the Mines. They await you at the mouth of the mines, southwest of here.", sourceObjective = "Seek out the Mistress of the Mines on Netherwing Ledge.", completion = "The miners are working hard but none dare step foot further into the mines. They choose death rather than being forced to mine deeper! It is going to be your job to carry out the duties and tasks that they failed to complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[11076] = { id = 11076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Up The Pieces...", description = "Much of our hard work lies scattered about in these mines. Carts full of cargo are littered across every inch of this mine! We just can't get to any of it with the current infestation.\n\nThat's where you come in, {name}. Your daily duty here at this mine is to collect the cargo left behind by the miners and deep mine workers.\n\nGather the nethermine cargo and return it to me or my sister.", sourceObjective = "The Mistress of the Mines at the Netherwing Mines in Shadowmoon Valley wants you to recover 15 Nethermine Cargo crates.", progress = "Have you gathered the cargo?", completion = "Well done, {name}. Return tomorrow for another mission into the depths of the mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[11077] = { id = 11077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragons are the Least of Our Problems", description = "That dragon waking up riled up a host of other nasty creatures in these mines. Two types are proving to be a thorn in the side of the Dragonmaw: Nethermine flayers and Nethermine ravagers. You must help us by killing them off. All I ask is your involvement once per day.\n\nGet in there and kill as many as you can!", sourceObjective = "The Dragonmaw Foreman at the Netherwing Mines in Shadowmoon Valley wants you to kill 15 Nethermine Flayers and 5 Nethermine Ravagers.", progress = "How's that flayer infestation problem coming along?", completion = "That'll be enough for today, overseer. Come back tomorrow for another round of clean up.", sourceObjectiveStatus = "unverified-source-field" }
quests[11078] = { id = 11078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Rule The Skies", description = "As ye've flown around, ye must have noticed the dragons above.  I trust ye haven't fallen victim ta their rage.  Help us put an end ta it, {name}!\n\nRivendark and Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon terrace ta the northeast.  Each has a perch on their respective domains.  I be wondering if ye and yer friends will go ta one, <lad/lass>, break open an egg with 35 apexis shards and attract the dragon down.\n\nBring me some teeth as proof.", sourceObjective = "Collect Dragon Teeth.", progress = "How fares yer mission, {name}?  I needn't tell ye how important this be ta our continued ability ta fly around up here.", completion = "Yes!  Those teeth look like they be sharp enough ta cut through just about anything!\n\nAnd let me encourage ye and yer friends ta keep up the good work!  Those dragons be fierce predators that make the skies wholly unsafe.\n\nYe might have noticed, too, the dragon scales.  I hear they be good fer making powerful cloaks if ye get one o' each o' their scales.  And if yer not happy with the cloak ya get, I'll be willing ta trade ye an apexis crystal fer it.", sourceObjectiveStatus = "unverified-source-field" }
quests[11079] = { id = 11079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fel Whip For Gahk", description = "Gahk think being smart is dumb sometimes.  Gahk not want to think.  Me want little {race} to smash big demons!\n\nDey have some chiefs, and da chiefs all have whips to hurt da little demons.  You bring Gahk a whip!\n\nYou challenge demon chief in forge camps at burning, green, fel crystal prism.  Use 35 apexis shards to get dem to come.  Dey called Galvanoth, Braxxus, Zarcsin and da Mo'arg Incinerator.", sourceObjective = "Collect a Fel Whip.", progress = "Yous have da whip?", completion = "Gahk like whip.  Maybe Gahk take whip and beat demons with it!\n\nMe say to {race} that {race} summon demon chiefs anytime {race} have friends and many shards.", sourceObjectiveStatus = "unverified-source-field" }
quests[11080] = { id = 11080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Relic's Emanation", description = "Now that you have felt the enlightening vibrations of the apexis relics, it is time for you to further your understanding of their workings.  We are very eager to benefit from your observations!\n\nAs you progress in your ability to attune to the relics, you will gain a higher level of knowledge.  This recognition will come in the form of an emanation from the relic.\n\nReturn to us when you have attained such an emanation.", sourceObjective = "Gain Apexis Emanations from an Apexis Relic.", progress = "Do you have the emanation from the apexis relic about you?", completion = "You continue to amaze us with your acumen as concerns the relics, {name}.  May we suggest that you practice with the relics at least once a day to maintain such a sharp edge to your mental acuity?", sourceObjectiveStatus = "unverified-source-field" }
quests[11081] = { id = 11081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Murkblood Revolt", description = "This document outlines a revolt planned by the Murkblood broken. It seems that the dragon was to be used as a diversion to draw attention away from their escape. Looking at all of the corpses littering the mine, it would be safe to assume that their plans failed.\n\nReturn the escape plans to the Mistress of the Mines.", sourceObjective = "Take the Murkblood Escape Plans to the Mistress of the Mines.", progress = "What's this?", completion = "Excellent work, overseer. Mor'ghor will hear of your outstanding service to the Dragonmaw.\n\nNow back to these Murkblood dogs. They plan an escape, eh? Dare they defy the one true lord of Outland? Their masters will pay for this!", sourceObjectiveStatus = "unverified-source-field" }
quests[11082] = { id = 11082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeker of Truth", description = "These miners are far too stupid to concoct any type of escape plan. We must find and punish the source. Venture into the depths of the mine and seek out the Murkblood overseers. If they have not been overcome by the denizens of the mine, they will undoubtedly be hiding.\n\nOnce you locate one, interrogate him until he reveals the true mastermind behind the escape. Return to me with the identity of this traitor and the hand of the overseer.", sourceObjective = "Find a Murkblood Overseer and interrogate him. Return to the Mistress of the Mines with the Murkblood information and the Hand of the Overseer.", progress = "Well? What's taking so long?", completion = "Nothing to say? Perhaps as he lies bleeding to death on the floor of this cursed mine he will remember... Remember what it means to cross the forces of Illidan!", sourceObjectiveStatus = "unverified-source-field" }
quests[11083] = { id = 11083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crazed and Confused", description = "Don't worry about this dragon, {name}. We've got plans for it...\n\nDeeper in this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off from the exit. Somehow, after a mere 2 days of isolation, they've lost all sense of decency.\n\nThey've resorted to cannibalism and the promotion of mayhem. We don't need that kind of madness in this place. Find 'em and kill 'em. All of 'em.", sourceObjective = "Ronag the Slave Driver in the Netherwing Mines of Shadowmoon Valley wants you to slay the Crazed Murkblood Foreman and 5 Crazed Murkblood Miners.", progress = "Is the problem \"solved\"?", completion = "Yeah, I don't understand it... You would think that they wouldn't even be that hungry after 2 days. Murkblood...\n\n<Ronag shakes his head.>\n\nDamn they're stupid...", sourceObjectiveStatus = "unverified-source-field" }
quests[11084] = { id = 11084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stand Tall, Captain!", description = "Well, well, well... still alive I see. That's good, because Mor'ghor has requested your presence in his tower at once. Get a move on!", sourceObjective = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "<Mor'ghor nods.>\n\nThat's right, I said captain. You've earned another promotion, {name}.\n\nYou certainly don't work like any fel orc I've ever seen. Keep this up and you might make overlord some day.\n\nNow get out there and take command. I would suggest you try and earn your Skybreaker wings.", sourceObjectiveStatus = "unverified-source-field" }
quests[11085] = { id = 11085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Skettis", description = "Hail, {name}.  I thank you for coming to my aid.\n\nThe arakkoa's monstrous birds knocked me from my nether ray while on a scouting mission.\n\nLet's get out of here, while we can.", sourceObjective = "Escort the Skyguard Prisoner to safety and report to Sky Sergeant Doryn.", progress = "Yes, {name}?", completion = "Thank you for rescuing one of our scouts, {name}.  We lose good people every day and there aren't enough new recruits to replace them.", sourceObjectiveStatus = "unverified-source-field" }
quests[11086] = { id = 11086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Twilight Portal", description = "One of your responsibilities as a captain of Dragonmaw is to snuff out Burning Legion activity in Outland. It is your duty to silence those that defy Lord Illidan!\n\nThe demons foolishly attempt to stabilize the portal found on the Twilight Ridge of western Nagrand. They must pay for their treachery, and you will be the orc that collects on their debt.\n\nTravel to the Twilight Ridge and lay waste to its inhabitants. You will be responsible for making at least one attack per day on their fortifications.", sourceObjective = "Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley wants you to kill 20 Deathshadow Agents.", progress = "It was our lord, after all, that banished the demons from Outland and closed their portals. All should bow down to the magnificence of Illidan.", completion = "Excellent work, captain! Lord Illidan will hear of your heroism!", sourceObjectiveStatus = "unverified-source-field" }
quests[11089] = { id = 11089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Cannon of Reth'hedron", description = "Reth'hedron now lords over the Twilight Ridge of Nagrand. An eredar of such power being loosed upon this world does not bode well for the Illidari. Alas, we do not have the resources required to slay Reth'hedron. Not with the war the Sha'tar have brought to the Black Temple. No... I have a better plan.\n\nYou will subdue Reth'hedron, banishing him back through the Twilight Portal. For this a soul cannon must be fashioned.\n\nReturn to me with the materials on this list.", sourceObjective = "Illidari Lord Balthas at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 2 Felsteel Bars, 1 Adamantite Frame, 1 Khorium Power Core and 1 Flawless Arcane Essence.", progress = "Have you gathered the components required to fashion the soul cannon?", completion = "<Balthas deftly combines the components you brought him.>\n\nYou are now ready for the second phase of the plan, captain.", sourceObjectiveStatus = "unverified-source-field" }
quests[11090] = { id = 11090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subdue the Subduer", description = "<Balthas holds up an alien looking device.>\n\nThis is a soul cannon. Its effects are devastating when attuned. This one is attuned to my blood. The same blood flowing through the veins of Reth'hedron - my brother. Aye, his misplaced allegiance will be the end of him.\n\nTake the cannon and fly to the Twilight Ridge in western Nagrand. Locate Reth'hedron and fire! You must stay on your mount and within range for the effects to take hold. Stand your ground against him and he will have no choice but to flee!", sourceObjective = "Illidari Lord Balthas at Dragonmaw Base Camp in Shadowmoon Valley has tasked you with using the Soul Cannon on Reth'hedron the Subduer in Nagrand.\n\nYou must also return the Soul Cannon.", progress = "Is it done?", completion = "He will be back, but for now the Legion's war against Lord Illidan is weakened. He shall know of your deeds, captain.", sourceObjectiveStatus = "unverified-source-field" }
quests[11091] = { id = 11091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Thank You", description = "You honor us with your efforts on our behalf.  And now there is someone that we would like for you to meet.\n\nJho'nass is our most trusted quartermaster.  He maintains a stock of goods that we provide for sale to only the most dedicated of friends to Ogri'la.\n\nYou are one such friend, {name}.\n\nWhen you find the time, go and speak with him.  As we understand it, he has prepared a little something for you as a token of our appreciation.", sourceObjective = "Speak with Jho'nass at Ogri'la in the Blade's Edge Mountains.", completion = "Hey, man, that's great.  We hear you've been doing good things.  That's cool.  We've got a feeling that you're going to make things right for us here in Ogri'la, and keep us safe, and everything nice and mellow.\n\nHere, take this.  It's nothing much, just a care package that we whipped up as a thanks for your effort.\n\nFeel free to look around at our goods.  We have a lot of really choice stuff that you're gonna want to get.", sourceObjectiveStatus = "unverified-source-field" }
quests[11092] = { id = 11092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hail, Commander!", description = "Captain {name}!\n\n<Taskmaster Varkule salutes you.>\n\nOverlord Mor'ghor has asked to see you in his chambers at once!", sourceObjective = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Lord Illidan himself has asked that I promote you to the rank of commander! This is unprecedented. You will be the first Dragonmaw to reach such a rank outside of the Black Temple.", sourceObjectiveStatus = "unverified-source-field" }
quests[11093] = { id = 11093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Nether Rays", description = "Nether rays are surprisingly loyal and obedient once properly trained.  Unfortunately the war on Skettis is taking a toll on them.\n\nWe have dozens of sorties a day - the poor fellows rarely get a break.  And with recent shortages on feed, if those blasted birdmen don't kill them on a mission then starvation will.\n\nIf you can lend a hand, take one of our rays to the woods in the south.  They don't mind warp chaser meat as long as it's a fresh kill.", sourceObjective = "Use the Nether Ray Cage in the woods south of Blackwind Landing and slay Blackwind Warp Chasers near the Hungry Nether Ray. Return to Skyguard Handler Deesak when you've completed your task.", progress = "You're back!  Did your ray behave well?", completion = "Thanks for taking care of the ray, {name}.  Goodness knows these guys fly much better when they're well-fed.  We don't want our boys getting shot down because their ray was too weak to fly.", sourceObjectiveStatus = "unverified-source-field" }
